1	// What the fleet DID — the counterpart to every other derivation here, which answers
2	// where to look. Pure: no clock, no I/O, no DOM.
3	//
4	// The page's panels are all fault-finding, and fault-finding has a blind spot: after
5	// a good week every count is zero, so a healthy fleet and a dead one render
6	// identically. Nothing on the page can tell them apart, because "nothing is wrong" and
7	// "nothing happened" are the same picture. This module is the other reading — closed
8	// work, scheduler runs, and which members moved at all — over a window of days.
9	//
10	// EVERY NUMBER COMES FROM A READ THE PAGE ALREADY MAKES. A per-member call to get a
11	// commit count would undo the budget work the whole client is built around, so the
12	// inputs are exactly the fleet loader's existing per-member reads: the first page of
13	// issues, the recent Actions runs, and the head commit whose date arrives with the sha
14	// the content cache is keyed by. Nothing here adds a request.
15	//
16	// WHAT THAT COSTS IS DEPTH, AND DEPTH IS DECLARED. One issue page is the most recent
17	// hundred issues by creation, and one runs page is the most recent thirty runs — so a
18	// day at the far end of the window is under-read rather than empty, and every series
19	// carries the horizon past which it stops being a count and starts being a floor.
20	
21	import { isParked, outcomeOf } from '../../../claudinite-tasks/public/work-item-grammar.mjs';
22	import { isSubstantiveCommit } from './substantive-commit.mjs';
23	import { isWorkItem } from './model.mjs';
24	
25	export const DAY_MS = 86400e3;
26	
27	const ms = (t) => (t == null ? null : new Date(t).getTime());
28	
29	// A UTC day. The queue's anchors and GitHub's timestamps are
30	// all UTC, so a local-time bucketing would put a member's midnight run on the wrong
31	// day depending on who is looking.
32	export const dayKey = (t) => new Date(t).toISOString().slice(0, 10);
33	
34	// The window's days, oldest first, including today. Built from keys rather than from
35	// arithmetic on a rendered date so a DST-free UTC ladder is the only thing anyone has
36	// to trust.
37	export function dayLadder(now, days) {
38	  const start = Math.floor(now / DAY_MS) * DAY_MS - (days - 1) * DAY_MS;
39	  return Array.from({ length: days }, (_, i) => dayKey(start + i * DAY_MS));
40	}
41	
42	// --- the daily series -----------------------------------------------------------
43	
44	// Work closed, runs finished and members moving, per day. `reads` is the fleet
45	// loader's raw per-member reads; a member that could not be read contributes nothing
46	// and is counted as unread rather than as a quiet day.
47	export function activitySeries(reads, { now, days = 14 } = {}) {
48	  const ladder = dayLadder(now, days);
49	  const index = new Map(ladder.map((d, i) => [d, i]));
50	  const blank = () => ladder.map((day) => ({
51	    day,
52	    work: { done: 0, delivered: 0, obsolete: 0, none: 0 },
53	    workClosed: 0,
54	    otherClosed: 0,
55	    runs: { success: 0, failure: 0, other: 0 },
56	    movers: new Set(),
57	  }));
58	
59	  const series = blank();
60	  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);
61	  // The oldest thing each read could see. A day before this is under-read for that
62	  // member — not quiet — and the series says so rather than drawing a confident zero.
63	  let issueHorizon = null;
64	  let runHorizon = null;
65	  const seen = (at, keep) => {
66	    const t = ms(at);
67	    if (t == null) return keep;
68	    return keep == null ? t : Math.max(keep, t);
69	  };
70	
71	  for (const read of readable) {
72	    const items = read.items ?? [];
73	    let oldestIssue = null;
74	    for (const i of items) {
75	      const created = ms(i.created_at);
76	      if (created != null) oldestIssue = oldestIssue == null ? created : Math.min(oldestIssue, created);
77	      if (i.state !== 'closed') continue;
78	      const at = ms(i.closed_at) ?? ms(i.updated_at);
79	      const slot = at == null ? undefined : index.get(dayKey(at));
80	      if (slot === undefined) continue;
81	      series[slot].movers.add(read.repo);
82	      if (isWorkItem(i)) {
83	        series[slot].workClosed += 1;
84	        series[slot].work[outcomeOf(i) ?? 'none'] += 1;
85	      } else {
86	        series[slot].otherClosed += 1;
87	      }
88	    }
89	    // A member whose page-1 window does not reach the start of the ladder truncates
90	    // the series for everyone, so the horizon is the LATEST such floor across members.
91	    if (!read.itemsComplete && oldestIssue != null) issueHorizon = seen(oldestIssue, issueHorizon);
92	
93	    let oldestRun = null;
94	    for (const r of read.runs ?? []) {
95	      const at = ms(r.created_at);
96	      if (at == null) continue;
97	      oldestRun = oldestRun == null ? at : Math.min(oldestRun, at);
98	      const slot = index.get(dayKey(at));
99	      if (slot === undefined) continue;
100	      series[slot].movers.add(read.repo);
101	      const bucket = r.status !== 'completed' ? 'other'
102	        : r.conclusion === 'success' ? 'success'
103	          : (r.conclusion === 'failure' || r.conclusion === 'timed_out' || r.conclusion === 'startup_failure') ? 'failure'
104	            : 'other';
105	      series[slot].runs[bucket] += 1;
106	    }
107	    if (oldestRun != null) runHorizon = seen(oldestRun, runHorizon);
108	
109	    // The default branch's tip. One date, so it marks the day that member last
110	    // landed something — not a commit count, and never drawn as one.
111	    const tip = ms(read.head?.committedAt);
112	    const tipSlot = tip == null ? undefined : index.get(dayKey(tip));
113	    if (tipSlot !== undefined) series[tipSlot].movers.add(read.repo);
114	  }
115	
116	  const rows = series.map((d) => ({ ...d, movers: [...d.movers].sort(), moved: d.movers.size }));
117	  const movedInWindow = new Set(rows.flatMap((d) => d.movers));
118	
119	  return {
120	    days: rows,
121	    from: ladder[0],
122	    to: ladder[ladder.length - 1],
123	    members: readable.length,
124	    unread: (reads ?? []).filter((r) => r?.error).length,
125	    moved: [...movedInWindow].sort(),
126	    quiet: readable.map((r) => r.repo).filter((r) => !movedInWindow.has(r)).sort(),
127	    totals: {
128	      workClosed: rows.reduce((n, d) => n + d.workClosed, 0),
129	      otherClosed: rows.reduce((n, d) => n + d.otherClosed, 0),
130	      runs: rows.reduce((n, d) => n + d.runs.success + d.runs.failure + d.runs.other, 0),
131	      runsFailed: rows.reduce((n, d) => n + d.runs.failure, 0),
132	    },
133	    // The day before which the series is a floor rather than a count, per source. Null
134	    // means every read reached past the window and the whole ladder is a real count.
135	    horizon: {
136	      issues: issueHorizon != null && issueHorizon > now - days * DAY_MS ? dayKey(issueHorizon) : null,
137	      runs: runHorizon != null && runHorizon > now - days * DAY_MS ? dayKey(runHorizon) : null,
138	    },
139	  };
140	}
141	
142	// --- what the machinery bought --------------------------------------------------
143	
144	// The window's work, and the same window before it. Two rules shape what may appear
145	// here, and both are the owner's:
146	//
147	//   NO VANITY TOTAL. Every figure is bounded by a window, because a number that only
148	//   grows says nothing about today. The comparison is against the preceding window of
149	//   the same length, so "more than last week" is a fact and not a feeling.
150	//
151	//   NOTHING INVENTED. No estimated hours, no saved-effort multiplier, no score. Each
152	//   figure is a count of things that are individually true and individually clickable.
153	//   A quantity nothing on this page measures does not get a tile with a guess in it.
154	export function fleetBenefits(reads, { now, windowDays = 7 } = {}) {
155	  const span = windowDays * DAY_MS;
156	  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);
157	
158	  const inWindow = (t, from, to) => t != null && t >= from && t < to;
159	
160	  const window = (from, to) => {
161	    let completed = 0;
162	    let unattended = 0;
163	    let parked = 0;
164	    let runs = 0;
165	    let runsFailed = 0;
166	    const members = new Set();
167	
168	    for (const read of readable) {
169	      for (const i of (read.items ?? []).filter(isWorkItem)) {
170	        // Decoded, never a literal label test: a member's items wear whatever
171	        // spelling the engine that filed them wrote (work-item's `statusOf`).
172	        const wasParked = isParked(i);
173	        // An item that needed a person is counted whether or not it has closed —
174	        // being parked IS the event, and the ones still sitting there are the whole
175	        // point. `updated_at` is when its label was last written, which is the
176	        // closest thing the queue leaves to "when it was handed over".
177	        if (wasParked && inWindow(ms(i.updated_at), from, to)) parked += 1;
178	
179	        if (i.state !== 'closed') continue;
180	        const at = ms(i.closed_at) ?? ms(i.updated_at);
181	        if (!inWindow(at, from, to)) continue;
182	        const outcome = outcomeOf(i);
183	        if (outcome === 'done' || outcome === 'delivered') {
184	          completed += 1;
185	          members.add(read.repo);
186	          // The parked label is the record of a human being pulled in: the queue puts
187	          // it on when a run cannot finish itself, and takes it off only when the item
188	          // is re-queued by hand. An item that closed without wearing it therefore ran
189	          // start to finish with nobody in the loop AT THE POINT IT CLOSED — an item
190	          // triaged and re-queued earlier in its life counts here too, and the panel
191	          // says so rather than claiming more than the labels can carry.
192	          if (!wasParked) unattended += 1;
193	        }
194	      }
195	      for (const r of read.runs ?? []) {
196	        if (!inWindow(ms(r.created_at), from, to)) continue;
197	        if (r.status !== 'completed') continue;
198	        runs += 1;
199	        if (r.conclusion !== 'success' && r.conclusion !== 'skipped' && r.conclusion !== 'cancelled') runsFailed += 1;
200	      }
201	    }
202	    return { completed, unattended, parked, runs, runsFailed, members: members.size };
203	  };
204	
205	  const current = window(now - span, now + 1);
206	  const previous = window(now - 2 * span, now - span);
207	
208	  // NO `converged` FIGURE. It counted members whose declaration carried a converge
209	  // datetime inside the window, and #1252 deleted that datetime — it recorded the
210	  // last full re-vendor rather than the last converge, so the tile was already
211	  // counting the wrong thing. Nothing this sweep reads can answer "converged in the
212	  // last N days": a member's installed versions say WHAT it holds, never when it
213	  // took it. The panel names the gap instead of approximating it, which is the rule
214	  // this figure broke twice over (#1001, #1008).
215	  return {
216	    windowDays,
217	    current,
218	    previous,
219	    members: readable.length,
220	  };
221	}
222	
223	// A window-over-window change, in the only form that is honest when the previous
224	// window may itself be under-read: the delta, and which way it points.
225	export function delta(current, previous) {
226	  if (!Number.isFinite(current) || !Number.isFinite(previous)) return { dir: 'flat', by: 0 };
227	  const by = current - previous;
228	  return { dir: by > 0 ? 'up' : by < 0 ? 'down' : 'flat', by: Math.abs(by) };
229	}
230	
231	// --- one member's commit history -------------------------------------------------
232	
233	// The last N days of a member's commits, as a flat oldest-first ladder — the shape a
234	// GitHub-style square grid draws straight from.
235	//
236	// The input is `/stats/commit_activity`: 52 weeks, each a UTC-Sunday start and seven
237	// daily counts. This is the ONE read on the fleet page that is not derived from
238	// something already fetched, which is why it is priced as decoration everywhere it
239	// appears — and why its three empty answers must stay distinguishable. `null` is "not
240	// read" (withheld, or GitHub still computing the statistics) and is NOT the same fact
241	// as an array of zeroes, which is a repo that genuinely did nothing.
242	//
243	// A day the year does not cover is `null` rather than `0` for the same reason: a
244	// window wider than the data is under-read at its far end, not quiet there.
245	export function commitDays(weeks, { now, days = 90, classes = null } = {}) {
246	  if (!Array.isArray(weeks)) return null;
247	
248	  const byDay = new Map();
249	  for (const w of weeks) {
250	    const start = Number(w?.week);
251	    if (!Number.isFinite(start)) continue;
252	    (w.days ?? []).forEach((count, i) => {
253	      byDay.set(dayKey(start * 1000 + i * DAY_MS), Number(count) || 0);
254	    });
255	  }
256	
257	  const ladder = dayLadder(now, days);
258	  // `meaningful` is the second series, and it is null wherever the commit LISTING did
259	  // not reach — a shorter window than the statistics cover, or a page that filled up
260	  // before the window's start. Null there, not zero: "we did not classify this day" is
261	  // not "nothing meaningful happened".
262	  const rows = ladder.map((day) => ({
263	    day,
264	    count: byDay.has(day) ? byDay.get(day) : null,
265	    meaningful: classes?.byDay?.has(day) ? classes.byDay.get(day).meaningful : null,
266	  }));
267	  const counted = rows.filter((r) => r.count != null);
268	  return {
269	    days: rows,
270	    buckets: bucketWeekly(rows),
271	    total: counted.reduce((n, r) => n + r.count, 0),
272	    peak: counted.reduce((n, r) => Math.max(n, r.count), 0),
273	    // Days inside the window the year of statistics did not reach. Stated rather than
274	    // drawn as blank squares that read as quiet ones.
275	    unread: rows.length - counted.length,
276	    // How far the second series reaches, so the graph can draw it over its own span
277	    // and the hover can say what the rest of the line is not claiming.
278	    classified: classes ? { from: classes.from, complete: classes.complete } : null,
279	  };
280	}
281	
282	// The same window in weeks, which is the resolution a QUARTER of history is legible
283	// at. Drawn daily, an ordinary repo's weekend is a trough and a Tuesday a spike, so a
284	// 90-point curve across a column is a sawtooth that hides the only thing the column is
285	// for: whether this repo is being worked on, and whether it always was.
286	//
287	// The daily counts are kept — they are the total, the peak and the hover — and only
288	// the drawn line is smoothed. Weeks run back from today, so the OLDEST bucket is the
289	// short one, and a week is null only when every day in it was unread; a week that was
290	// partly read is a real sum over what there was.
291	const WEEK = 7;
292	
293	export function bucketWeekly(rows) {
294	  const out = [];
295	  for (let end = rows.length; end > 0; end -= WEEK) {
296	    const slice = rows.slice(Math.max(0, end - WEEK), end);
297	    const read = slice.filter((r) => r.count != null);
298	    const classified = slice.filter((r) => r.meaningful != null);
299	    out.unshift({
300	      from: slice[0].day,
301	      to: slice[slice.length - 1].day,
302	      days: slice.length,
303	      count: read.length ? read.reduce((n, r) => n + r.count, 0) : null,
304	      // The same rule as `count`, one series down: a week nothing classified is null,
305	      // and the drawn line breaks there rather than dropping to the floor.
306	      meaningful: classified.length ? classified.reduce((n, r) => n + r.meaningful, 0) : null,
307	    });
308	  }
309	  return out;
310	}
311	
312	// --- meaningful against machinery ------------------------------------------------
313	
314	// Which of a member's window commits were GENUINE PROJECT WORK, per day. The test is
315	// the claudinite-tasks pack's own (`isSubstantiveCommit`), so a member reads as quiet
316	// here exactly when its own preconditions read the repo as not having moved — a second
317	// notion of "meaningful" would mark a member sleepy on the commits its scheduler counts
318	// as movement.
319	//
320	// THE CHEAP TEST, and the page says so. The listing carries the message and the
321	// author, which is every exclusion but one: the corpus-only exclusion (a commit that
