336	    if (at == null) continue;
337	    const day = dayKey(at);
338	    if (!byDay.has(day)) byDay.set(day, { total: 0, meaningful: 0 });
339	    const row = byDay.get(day);
340	    row.total += 1;
341	    if (!isSubstantiveCommit(c)) continue;
342	    row.meaningful += 1;
343	    if (lastMeaningfulAt === null || at > lastMeaningfulAt) lastMeaningfulAt = at;
344	  }
