1	// The Work board, as data — lanes, marks and a schedule grid on a time axis
2	// ([docs/work-board.md](../../docs/work-board.md)). Pure: no clock of its own, no DOM.
3	//
4	// WHY A BOARD AND NOT A TABLE. The three table views answer *what is stuck*, one row
5	// per piece of work. They cannot answer the three questions this page is opened with —
6	// what will the next few days look like, where is the flow broken, and how much of it
7	// lands on a person — because each needs two things on one row, or a time under them.
8	//
9	// EVERY MARK IS READ, NEVER INFERRED. A label, a body line, a timestamp, or a task's
10	// own declaration; and a field the listing does not carry is `notRead`, never 0. That
11	// is the one rule this whole file is built to keep: the board's authority comes from
12	// every mark on it being traceable to a field a reader can go and look at.
13	//
14	// THE LANE IS THE FLOW. A row is one connected component of the edge graph — never a
15	// task (which hides the chain: an approval park is nothing without the PR it holds) and
16	// never a kind (which puts the two ends of one `Blocked-by` edge in different rows,
17	// and the edge is the finding).
18	
19	import {
20	  isQueueItem, parseWorkItemBody, parseWorkItemTitle, outcomeOf, statusOf, labelNames,
21	} from '../../../claudinite-tasks/public/work-item-grammar.mjs';
22	import {
23	  STATUS_NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_FAILURE, STATUS_RUNNING_AGENT,
24	  STATUS_RUNNING_EXECUTOR, STATUS_READY, PARK_PREFIX, PARK_KINDS, ORIGIN_AD_HOC, ASKED_FOR_ORIGINS,
25	} from '../../../claudinite-tasks/public/task-constants.mjs';
26	import { nextAnchor } from './task-calendar.mjs';
27	
28	// Every origin a person's action produces, as against the schedule's own.
29	const askedForOrigins = () => ASKED_FOR_ORIGINS;
30	
31	const DAY = 86400e3;
32	
33	// SEVEN BACK, TODAY, FOUR AHEAD. Four days ahead is the honest horizon — past it every
34	// prediction is "the same daily ticks again" — and seven back is the week of record the
35	// ledger above compares, which is what gives the task grid a past beside its future.
36	export const DAYS_BACK = 7;
37	export const DAYS_AHEAD = 4;
38	
39	// How many rows a group draws before it collapses the rest into one line. Four is what
40	// fits above the fold beside the other three groups; the rest are named, never dropped.
41	export const GROUP_CAP = 4;
42	
43	// When a plain issue is ROTTING. Fourteen days of nobody touching it is the bar the
44	// queue's own janitor uses, so the board and the queue agree about what stale means.
45	export const ROT_DAYS = 14;
46	
47	const ms = (t) => (t == null ? null : new Date(t).getTime());
48	const dayOf = (t) => new Date(t).toISOString().slice(0, 10);
49	
50	// The board's own axis. Every column carries the repo's daily anchor, because that is
51	// where every scheduled thing on the board sits.
52	export function axisOf(now, schedule, { back = DAYS_BACK, ahead = DAYS_AHEAD } = {}) {
53	  const today = Math.floor(now / DAY) * DAY;
54	  const hour = Number.isFinite(schedule?.dailyHour) ? schedule.dailyHour : 0;
55	  const days = [];
56	  for (let i = -back; i <= ahead; i += 1) {
57	    const start = today + i * DAY;
58	    days.push({
59	      day: dayOf(start),
60	      start,
61	      end: start + DAY,
62	      anchorAt: start + hour * 3600e3,
63	      past: i < 0,
64	      today: i === 0,
65	      future: i > 0,
66	    });
67	  }
68	  return { days, now, from: days[0].start, to: days[days.length - 1].end, dailyHour: hour };
69	}
70	
71	// --- the edge graph ------------------------------------------------------------------
72	
73	// Every edge the listings carry, in one direction each: from the thing that WAITS to
74	// the thing it waits on.
75	//
76	// `Refs #n` is deliberately absent: a PR's body is not stored by the page's projection
77	// (only the issue it closes is parsed out of it before it is dropped), so an edge that
78	// would need it is not read rather than guessed at.
79	export function edgesOf(items, prs) {
80	  const edges = [];
81	  for (const item of items) {
82	    const body = parseWorkItemBody(item.body);
83	    for (const target of body.blockedBy) edges.push({ from: item.number, to: target, kind: 'blocked-by' });
84	    if (body.endsWhen) edges.push({ from: item.number, to: body.endsWhen, kind: 'ends-when' });
85	  }
86	  for (const pr of prs) {
87	    if (pr.closesIssue) edges.push({ from: `pr:${pr.number}`, to: pr.closesIssue, kind: 'closes' });
88	  }
89	  return edges;
90	}
91	
92	// The connected components of that graph. A lone node is a component of one, which is
93	// what lets a plain issue nobody links to still be a row when it earns one.
94	export function componentsOf(nodes, edges) {
95	  const parent = new Map(nodes.map((n) => [n, n]));
96	  const find = (n) => {
97	    if (!parent.has(n)) parent.set(n, n);
98	    while (parent.get(n) !== n) { parent.set(n, parent.get(parent.get(n))); n = parent.get(n); }
99	    return n;
100	  };
101	  const union = (a, b) => { const ra = find(a); const rb = find(b); if (ra !== rb) parent.set(ra, rb); };
102	  for (const e of edges) { if (parent.has(e.from) || parent.has(e.to)) union(e.from, e.to); }
103	  const groups = new Map();
104	  for (const n of nodes) {
105	    const root = find(n);
106	    if (!groups.has(root)) groups.set(root, []);
107	    groups.get(root).push(n);
108	  }
109	  return [...groups.values()];
110	}
111	
112	// --- where a mark sits in time ---------------------------------------------------------
113	
114	// An item's PREDICTED time, and why it is there. This is the board's single most
115	// load-bearing derivation, so each branch names the field it read:
116	//
117	//   a stamped `Not-before`     → that instant. The stamp IS the schedule.
118	//   blocked by a PR            → now, and "when you merge it" — a person's move.
119	//   blocked by an item that has a time → after it.
120	//   blocked by a plain issue nobody is scheduled to close → NO TIME, and the lane is
121	//                                drawn broken. That is the finding, not a gap.
122	//   ready                      → the next daily anchor, the tick it will be drained on.
123	//   parked or running          → now, where the person and the machine both are.
124	export function placeItem(item, { now, axis, byNumber, moversByNumber, depth = 0 }) {
125	  const status = statusOf(item);
126	  const body = parseWorkItemBody(item.body);
127	  if (status && status.startsWith(PARK_PREFIX)) return { at: now, why: 'parked', kind: 'park' };
128	  if (status === STATUS_RUNNING_AGENT || status === STATUS_RUNNING_EXECUTOR) {
129	    return { at: now, why: 'running', kind: 'running' };
130	  }
131	  const notBefore = ms(body.notBefore);
132	  if (notBefore !== null && Number.isFinite(notBefore)) {
133	    return { at: notBefore, why: `Not-before ${body.notBefore}`, kind: 'blocked-date' };
134	  }
135	  // An unreadable `Not-before` is FLAGGED, never guessed: a relative date a person
136	  // meant is a date the machine will treat as absent, and that is worth saying.
137	  if (body.notBefore) return { at: null, why: `a relative date the parser does not read: ${body.notBefore}`, kind: 'unreadable-date', flagged: true };
138	
139	  for (const target of body.blockedBy) {
140	    const mover = moversByNumber.get(target);
141	    if (mover?.kind === 'pr') return { at: now, why: `#${target} lands when you merge PR #${mover.number}`, kind: 'blocked-pr' };
142	    const blocker = byNumber.get(target);
143	    if (!blocker) continue;
144	    if (!isQueueItem(blocker)) {
145	      // A plain issue no task and no PR will close. Nothing on the board moves it, so
146	      // the downstream item has no time at all and its lane is drawn broken.
147	      return { at: null, why: `no one is scheduled to close #${target}`, kind: 'broken', broken: true, blocker: target };
148	    }
149	    if (depth >= 4) break;                              // a cycle, or a chain past reading
150	    const upstream = placeItem(blocker, { now, axis, byNumber, moversByNumber, depth: depth + 1 });
151	    if (upstream.at === null) return { ...upstream, why: `after #${target}: ${upstream.why}` };
152	    return { at: upstream.at, why: `after #${target}`, kind: 'blocked-item' };
153	  }
154	
155	  if (status === STATUS_READY) {
156	    return { at: nextDailyAnchor(now, axis), why: 'ready — the next scheduler tick', kind: 'ready' };
157	  }
158	  // An item on no queue mark at all: nothing will pick it up, and saying so is the
159	  // whole reason it is on the board.
160	  return { at: null, why: 'unmarked — no queue status, nothing will pick this up', kind: 'unmarked', flagged: true };
161	}
162	
163	export const nextDailyAnchor = (now, axis) =>
164	  axis.days.find((d) => d.anchorAt > now)?.anchorAt ?? null;
165	
166	// --- the Now group --------------------------------------------------------------------
167	
168	// Why a pull request waits for a person — three different reasons drawn as one amber
169	// flag, and named apart in the panel because the reader's next move differs.
170	export function prWaits(pr, { item = null, declaration = null } = {}) {
171	  const merge = item ? parseWorkItemBody(item.body).merge : null;
172	  if (declaration && declaration.automerge === 'nothing') {
173	    return { waits: true, why: `${declaration.key ?? 'its task'} declares automerge: nothing` };
174	  }
175	  if (item && !merge) return { waits: true, why: 'its item carries no Merge policy' };
176	  if (!item) return { waits: true, why: 'no work item names this PR — nothing will land it' };
177	  // The run's own converge verdict lives in a comment this listing does not fetch, so
178	  // a PR whose item DOES authorize a merge is "still open" rather than "waits for you".
179	  return { waits: false, why: `its item authorizes ${merge}`, notRead: 'the run\'s own AUTOMERGE verdict is in a comment this page has not fetched' };
180	}
181	
182	// --- the Scheduled group's task × day grid ---------------------------------------------
183	
184	const OUTCOME_CELL = { done: 'ran', delivered: 'ran', obsolete: 'declined' };
185	
186	// One row per scheduled task, one cell per day. A cell's state is form plus the
187	// semantic set, never colour alone.
188	//
189	// A FAILURE PARK LANDS ON ITS OWN TASK'S ROW, followed by whatever the task did after
190	// it — so where the declaration holds its lane on a failure, a hatched cell followed
191	// by filled ones is the record disagreeing with the roster's claim that the lane is
192	// held, read left to right on one line. There is no separate held-lanes row, because
193	// the contradiction is a row fact.
194	//
195	// A task gets its OWN row when it can fire on any day of the axis — a daily cadence,
196	// an elapsed one of a day or under, or no cadence term at all (asked at every tick).
197	// Anything on a longer cadence shares one row: the reader's question of a weekly
198	// task is whether it fired at all this week, not which weekday it prefers.
199	const onOwnRow = (row) => row.periodMs === null || row.periodMs <= DAY;
200	
201	export function scheduleGrid(rows, items, axis, { now, schedule }) {
202	  // A `request` task is never on the schedule (`scheduled: false`), and a
203	  // declaration this could not read (`scheduled: null`) is not put on it either — a
204	  // row there would be a claim about a future nothing was read for.
205	  const scheduled = rows.filter((r) => r.scheduled);
206	  const daily = scheduled.filter(onOwnRow);
207	  const others = scheduled.filter((r) => !onOwnRow(r));
208	
209	  const cellsFor = (row) => axis.days.map((day) => {
210	    const occurrences = items.filter((i) => {
211	      const parsed = parseWorkItemTitle(i.title);
212	      const key = parsed ? `${parsed.pack}/${parsed.task}` : null;
213	      if (key !== row.key) return false;
214	      const when = i.state === 'closed' ? ms(i.closed_at) : ms(i.updated_at);
215	      return when !== null && when >= day.start && when < day.end;
216	    });
217	
218	    if (day.future) {
219	      const at = nextAnchorFor(row, now, schedule);
220	      if (at === null || at < day.start || at >= day.end) return { day: day.day, state: 'none', count: 0 };
221	      // Predicted and WILL DECLINE are told apart by height, never by dash pattern,
222	      // which at three pixels is invisible.
223	      const willDecline = row.lastClosed?.outcome === 'obsolete';
224	      return { day: day.day, state: willDecline ? 'will-decline' : 'predicted', count: 0 };
225	    }
226	
227	    const open = occurrences.filter((i) => i.state === 'open');
228	    const park = open.find((i) => statusOf(i) === STATUS_NEEDS_HUMAN_FAILURE);
229	    if (park) return { day: day.day, state: 'failure-park', count: 1, number: park.number };
230	    const approval = open.find((i) => statusOf(i) === STATUS_NEEDS_HUMAN_APPROVAL);
231	    if (approval) return { day: day.day, state: 'parked', count: 1, number: approval.number };
232	    const running = open.find((i) => [STATUS_RUNNING_AGENT, STATUS_RUNNING_EXECUTOR].includes(statusOf(i)));
233	    if (running) return { day: day.day, state: 'running', count: 1, number: running.number };
234	
235	    const closed = occurrences.filter((i) => i.state === 'closed');
236	    if (!closed.length) return { day: day.day, state: 'none', count: 0 };
237	    const states = closed.map((i) => OUTCOME_CELL[outcomeOf(i)] ?? 'declined');
238	    return {
239	      day: day.day,
240	      state: states.includes('ran') ? 'ran' : 'declined',
241	      count: closed.length,
242	      numbers: closed.map((i) => i.number),
243	    };
244	  });
245	
246	  const gridRows = daily.map((row) => ({ key: row.key, task: row.task, pack: row.pack, cells: cellsFor(row), row }));
247	  if (others.length) {
248	    gridRows.push({
249	      key: 'other-cadences',
250	      task: `${others.length} on a longer cadence`,
251	      pack: null,
252	      collapsed: others.map((r) => r.key),
253	      cells: axis.days.map((day) => {
254	        const merged = others.map((row) => cellsFor(row).find((c) => c.day === day.day));
255	        const live = merged.filter((c) => c && c.state !== 'none');
256	        if (!live.length) return { day: day.day, state: 'none', count: 0 };
257	        const worst = ['failure-park', 'parked', 'running', 'ran', 'declined', 'predicted', 'will-decline']
258	          .find((s) => live.some((c) => c.state === s));
259	        return { day: day.day, state: worst, count: live.reduce((n, c) => n + (c.count || 1), 0) };
260	      }),
261	    });
262	  }
263	  return gridRows;
264	}
265	
266	// Only a `due:` cadence is on the calendar; every other reading has no instant to
267	// predict, so its future cells stay empty rather than guessed.
268	const nextAnchorFor = (row, now, schedule) => {
269	  if (row.nextAsk?.at) return ms(row.nextAsk.at);
270	  if (row.cadence?.kind !== 'due' || !schedule) return null;
271	  const at = nextAnchor(row.cadence.cadence, schedule, now);
272	  return at ? ms(at) : null;
273	};
274	
275	// --- tomorrow's human workload -----------------------------------------------------------
276	
277	// The Now group's header sentence, DERIVED and never a tile: the PRs waiting now, plus
278	// the scheduled runs whose own declaration cannot land the PR they will open. It is the
279	// `automerge` field read against each task's cadence, not a guess about tomorrow — and
280	// a task with no cadence term is counted apart, because "a day" is a promise its
281	// declaration never made.
282	export function workloadLine(waitingPrs, rows, { schedule, now }) {
283	  const producers = rows.filter((r) => r.scheduled
284	    && (r.declaration?.automerge === 'nothing' || r.declaration?.automerge == null));
285	  const daily = producers.filter((r) => r.periodMs !== null && r.periodMs <= DAY);
286	  const rest = producers.filter((r) => r.periodMs !== null && r.periodMs > DAY);
287	  const movement = producers.filter((r) => r.periodMs === null);
288	  const parts = [`${waitingPrs} open PR${waitingPrs === 1 ? '' : 's'}`];
289	  parts.push(waitingPrs ? 'every one waits for a person' : 'nothing waits for a person');
290	  if (daily.length) parts.push(`+${daily.length} a day from ${daily.map((r) => r.task).slice(0, 2).join(', ')}${daily.length > 2 ? ` +${daily.length - 2}` : ''}`);
291	  if (rest.length) parts.push(`${rest.length} more on longer cadences`);
292	  if (movement.length) parts.push(`${movement.length} more on movement`);
293	  return parts.join(' · ');
294	}
295	
296	// --- the quiet tail -------------------------------------------------------------------
297	
298	// One ruled line, not a group: the plain issues on no edge, counted by what matters.
299	export function quietTail(issues, edges, now) {
300	  const onEdge = new Set(edges.flatMap((e) => [e.from, e.to]));
301	  const quiet = issues.filter((i) => !isQueueItem(i) && !onEdge.has(i.number));
302	  const has = (i, label) => labelNames(i).includes(label);
303	  const rotting = quiet.filter((i) => (now - (ms(i.updated_at) ?? now)) >= ROT_DAYS * DAY);
304	  return {
305	    total: quiet.length,
306	    rotting: rotting.length,
307	    quickWin: quiet.filter((i) => has(i, 'quick-win')).length,
308	    needsDecision: quiet.filter((i) => has(i, 'needs-decision')).length,
309	    items: quiet.map((i) => ({
310	      number: i.number, title: i.title,
311	      idleDays: Math.floor((now - (ms(i.updated_at) ?? now)) / DAY),
312	      quickWin: has(i, 'quick-win'),
313	      needsDecision: has(i, 'needs-decision'),
314	    })).sort((a, b) => b.idleDays - a.idleDays),
315	  };
316	}
317	
318	// --- the whole board --------------------------------------------------------------------
319	
320	export function buildBoard({ rows = [], items = [], prs = [], now, schedule = null } = {}) {
321	  const axis = axisOf(now, schedule);
322	  const open = items.filter((i) => i.state === 'open');
323	  const byNumber = new Map(items.map((i) => [i.number, i]));
324	  const moversByNumber = new Map(prs.filter((p) => p.closesIssue).map((p) => [p.closesIssue, { kind: 'pr', number: p.number }]));
325	  const declarationFor = new Map(rows.map((r) => [r.key, { ...r.declaration, key: r.key }]));
326	  const edges = edgesOf(open, prs);
327	
328	  // NOW — every open PR, wired to what it closes.
329	  const nowRows = prs.filter((p) => !p.merged_at).map((pr) => {
330	    const item = pr.closesIssue ? byNumber.get(pr.closesIssue) : null;
331	    const parsed = item ? parseWorkItemTitle(item.title) : null;
332	    const declaration = parsed ? declarationFor.get(`${parsed.pack}/${parsed.task}`) : null;
333	    const flag = prWaits(pr, { item, declaration });
334	    return {
335	      id: `pr:${pr.number}`,
336	      kind: 'pr',
337	      gutter: `#${pr.number}${pr.closesIssue ? ` → #${pr.closesIssue}` : ''}`,
338	      title: pr.title,
339	      openedAt: ms(pr.created_at),
340	      waits: flag.waits,
341	      why: flag.why,
342	      notRead: flag.notRead ?? null,
343	      marks: [{ kind: 'bar', from: ms(pr.created_at), to: now, flag: flag.waits }],
344	    };
345	  }).sort((a, b) => (b.waits ? 1 : 0) - (a.waits ? 1 : 0) || a.openedAt - b.openedAt);
346	
347	  // FLOWS — the items somebody asked for, and the plain issues that block them, at
348	  // their predicted time.
349	  const askedFor = askedForOrigins();
350	  const wasAsked = (i) => labelNames(i).some((n) => askedFor.includes(n));
351	  const asked = open.filter((i) => isQueueItem(i) && wasAsked(i));
352	  const parkedOrRunning = open.filter((i) => isQueueItem(i) && !wasAsked(i)
353	    && (statusOf(i)?.startsWith(PARK_PREFIX) || [STATUS_RUNNING_AGENT, STATUS_RUNNING_EXECUTOR].includes(statusOf(i))));
354	  const flowItems = [...asked, ...parkedOrRunning];
355	  const flowRows = flowItems.map((item) => {
356	    const place = placeItem(item, { now, axis, byNumber, moversByNumber });
357	    const status = statusOf(item);
358	    const parkKind = status?.startsWith(PARK_PREFIX) ? status.slice(PARK_PREFIX.length) : null;
359	    return {
360	      id: `item:${item.number}`,
361	      kind: 'item',
362	      gutter: `#${item.number}`,
363	      title: item.title,
364	      at: place.at,
365	      why: place.why,
366	      place: place.kind,
367	      broken: Boolean(place.broken),
368	      blocker: place.blocker ?? null,
369	      flagged: Boolean(place.flagged),
370	      parkKind: parkKind && PARK_KINDS.includes(parkKind) ? parkKind : (parkKind ? 'failure' : null),
371	      marks: [markFor(place, parkKind, now)],
372	      finding: place.broken || place.flagged ? place.why : null,
373	    };
374	  }).sort((a, b) => (b.broken ? 1 : 0) - (a.broken ? 1 : 0)
375	    || (a.at ?? Infinity) - (b.at ?? Infinity)
376	    || a.gutter.localeCompare(b.gutter));
377	
378	  const grid = scheduleGrid(rows, items, axis, { now, schedule });
379	  const quiet = quietTail(items.filter((i) => i.state === 'open'), edges, now);
380	  const waiting = nowRows.filter((r) => r.waits).length;
381	
382	  const capped = (list) => ({ shown: list.slice(0, GROUP_CAP), more: Math.max(0, list.length - GROUP_CAP), all: list });
383	
384	  return {
385	    axis,
386	    groups: [
387	      { id: 'now', title: 'Now', count: nowRows.length, sentence: workloadLine(waiting, rows, { schedule, now }), ...capped(nowRows) },
388	      {
389	        id: 'flows', title: 'Flows', count: flowRows.length,
390	        sentence: flowRows.length
391	          ? `blocked, parked, waiting — placed at their predicted run time${flowRows.some((r) => r.broken) ? ' · a broken lane has none' : ''}`
392	          : 'nothing is blocked, parked or waiting',
393	        ...capped(flowRows),
394	      },
395	      {
396	        id: 'scheduled', title: 'Scheduled', count: grid.length,
397	        sentence: `the daily anchor is ${String(axis.dailyHour).padStart(2, '0')}:00 UTC`,
398	        shown: grid, more: 0, all: grid, grid: true,
399	      },
400	    ],
401	    quiet,
402	    edges,
403	  };
404	}
405	
406	// One mark, from a placement. Form before colour: a park's kind is its glyph, a
407	// running item is filled, a queued one is hollow, and an item on no mark is dashed.
408	function markFor(place, parkKind, now) {
409	  if (place.kind === 'park') return { kind: 'park', at: now, park: parkKind?.replace(`${PARK_PREFIX}`, '') ?? 'failure' };
410	  if (place.kind === 'running') return { kind: 'running', at: now };
411	  if (place.at === null) return { kind: 'unmarked', at: null };
412	  return { kind: 'queued', at: place.at, broken: Boolean(place.broken) };
413	}
