1	// The fleet page's top block, as data. Everything above the members grid — Start
2	// here, The machine, the Got/Cost/Speed ledger, the totals and the pulse — reduced to
3	// one object the view renders without deciding anything.
4	//
5	// WHY IT IS A MODULE AND NOT THE VIEW. Every figure on that block is a window against
6	// the previous window, and every one of them can be UNKNOWN: a member that does not
7	// fold, a fold that predates a field, a rate table nobody set. Those three states —
8	// a number, *not recorded*, and (for money) *unpriced* — have to be decided once,
9	// where they can be tested, rather than in the branch of a template.
10	//
11	// NOTHING HERE FETCHES. It reduces over the reads the sweep already made: each
12	// member's decoded fold, its issues and PRs, its declaration. The request budget is
13	// unchanged by every figure below.
14	
15	import { priceWindow, RATES_KEY } from './pricing.mjs';
16	import { DAY_MS, dayKey, dayLadder } from './activity.mjs';
17	import {
18	  isQueueItem, isParked, outcomeOf,
19	} from '../../../claudinite-tasks/public/work-item-grammar.mjs';
20	
21	// The block's own window. Seven days against the seven before them, over a 14-day
22	// ladder — which is also the sparklines' and the pulse's span, so a figure, its delta
23	// and its shape all read the same stretch of days.
24	export const WINDOW_DAYS = 7;
25	export const LADDER_DAYS = 14;
26	
27	// How long an open item sits before it is STUCK. Three days is the spec's own bound,
28	// and it is the figure that feeds Start here.
29	export const STUCK_DAYS = 3;
30	
31	const ms = (t) => (t == null ? null : new Date(t).getTime());
32	const finite = (n) => (typeof n === 'number' && Number.isFinite(n) ? n : null);
33	
34	// Sum a field across whatever knew it, or `null`. NEVER 0 for "nobody answered": the
35	// whole point of the fold's absence rule is lost the moment a page adds up an empty
36	// list and prints the total.
37	export function sumKnown(values) {
38	  const known = (values ?? []).map(finite).filter((n) => n !== null);
39	  return known.length ? known.reduce((a, b) => a + b, 0) : null;
40	}
41	
42	// A quantile over a sample, by nearest rank. `null` on an empty sample — a median of
43	// nothing is not zero.
44	export function quantile(values, p) {
45	  const sorted = (values ?? []).map(finite).filter((n) => n !== null).sort((a, b) => a - b);
46	  if (!sorted.length) return null;
47	  const rank = Math.min(sorted.length - 1, Math.max(0, Math.ceil(p * sorted.length) - 1));
48	  return sorted[rank];
49	}
50	
51	// --- the day ladder ----------------------------------------------------------------
52	
53	// One row per day across the whole fleet: every scalar the ledger reads, summed over
54	// the members that knew it, plus the two sub-maps the pricing and the lead times need.
55	// A day nobody folded carries `null` everywhere and `folded: false`, which is what
56	// draws a blank column rather than a floor.
57	export function fleetDays(folding, { now, days = LADDER_DAYS } = {}) {
58	  const ladder = dayLadder(now, days);
59	  const SCALARS = [
60	    'sessions', 'userMessages', 'tokensIn', 'tokensOut', 'tokenSessions',
61	    'humanSeconds', 'agentSeconds',
62	    'commits', 'linesAdded', 'linesRemoved', 'releases',
63	  ];
64	  return ladder.map((day) => {
65	    const rows = folding.map((r) => r.usage?.days?.[day]).filter(Boolean);
66	    const out = { day, folded: rows.length > 0, members: rows.length };
67	    for (const field of SCALARS) out[field] = sumKnown(rows.map((row) => row[field]));
68	    // Both check scopes together, as `growthSeries` reads them: "how often did the
69	    // checks catch something today" is one question.
70	    const scopes = rows.flatMap((row) => Object.values(row.checks ?? {}));
71	    out.caught = scopes.length
72	      ? scopes.reduce((n, s) => n + (s.failures ?? 0) + (s.ciFailures ?? 0), 0) : null;
73	    out.checkRuns = scopes.length ? scopes.reduce((n, s) => n + (s.runs ?? 0), 0) : null;
74	    out.checkErrors = scopes.length ? scopes.reduce((n, s) => n + (s.errors ?? 0), 0) : null;
75	    // Kept as rows rather than summed: the pricing reduction wants the per-model split
76	    // and the lead times want one entry per PR, both across the whole window.
77	    out.tokensByModel = rows.map((row) => ({ tokensByModel: row.tokensByModel }));
78	    out.prs = rows.flatMap((row) => Object.entries(row.prs ?? {}));
79	    // Which member released, so the releases figure can name them rather than count.
80	    out.releasedBy = folding
81	      .filter((r) => finite(r.usage?.days?.[day]?.releases) > 0)
82	      .map((r) => r.repo);
83	    // …and which moved at all, for the pulse's hover.
84	    out.movedBy = folding.filter((r) => finite(r.usage?.days?.[day]?.sessions) > 0).map((r) => r.repo);
85	    return out;
86	  });
87	}
88	
89	// The two windows the block compares, as day-row slices. `current` ends today
90	// inclusive; `previous` is the seven days before it.
91	export function windowsOf(rows, { now, windowDays = WINDOW_DAYS } = {}) {
92	  const from = dayKey(now - (windowDays - 1) * DAY_MS);
93	  const prevFrom = dayKey(now - (2 * windowDays - 1) * DAY_MS);
94	  return {
95	    current: rows.filter((r) => r.day >= from),
96	    previous: rows.filter((r) => r.day >= prevFrom && r.day < from),
97	    from,
98	    to: dayKey(now),
99	    prevFrom,
100	    prevTo: dayKey(now - windowDays * DAY_MS),
101	  };
102	}
103	
104	// --- merged pull requests ----------------------------------------------------------
105	
106	// Every PR merged inside the window, from the two sources that reach different depths
107	// and DEDUPED on its number, since a PR merged in the last day or two is in both.
108	//
109	// The live listing carries the merge date and the issue a PR closes but no lead times;
110	// the fold carries the lead times the reader needs and reaches further back. So a PR
111	// seen live is joined to the issue in the same read where one is there — which is what
112	// makes `issue → merged` answerable for the days the fold has not folded yet.
113	export function mergedPrsIn(reads, dayRows, { repoOf = (r) => r.repo } = {}) {
114	  const seen = new Map();
115	  const from = dayRows[0]?.day ?? null;
116	  const to = dayRows[dayRows.length - 1]?.day ?? null;
117	
118	  for (const read of reads) {
119	    const issues = new Map((read.items ?? []).map((i) => [i.number, i]));
120	    for (const pr of read.prs ?? []) {
121	      const merged = pr.merged_at ?? null;
122	      if (!merged) continue;
123	      const day = merged.slice(0, 10);
124	      if (from && (day < from || day > to)) continue;
125	      const issue = pr.closesIssue ? issues.get(pr.closesIssue) : null;
126	      seen.set(`${repoOf(read)}#${pr.number}`, {
127	        repo: repoOf(read),
128	        number: pr.number,
129	        day,
130	        source: 'live',
131	        leadHours: hoursBetweenIso(pr.created_at, merged),
132	        issueLeadHours: issue ? hoursBetweenIso(issue.created_at, merged) : null,
133	        sessionToMergeHours: null,
134	      });
135	    }
136	  }
137	
138	  for (const row of dayRows) {
139	    for (const [number, lead] of row.prs) {
140	      const key = `${row.day}#${number}`;
141	      // The fold's row is the fuller record — it carries the session lead time nothing
142	      // live can answer — so it wins wherever both sources have the same PR. Members
143	      // are not distinguishable in a fold row's key, so the day stands in for the repo;
144	      // a collision would need two members to merge the same PR number on one day, and
145	      // it costs one row of a sample rather than a figure.
146	      const live = [...seen.values()].find((p) => String(p.number) === String(number) && p.day === row.day);
147	      if (live) { Object.assign(live, { ...lead, source: 'fold' }); continue; }
148	      seen.set(key, { repo: null, number, day: row.day, source: 'fold', ...lead });
149	    }
150	  }
151	  return [...seen.values()];
152	}
153	
154	const hoursBetweenIso = (from, to) => {
155	  const a = ms(from);
156	  const b = ms(to);
157	  if (a === null || b === null || !Number.isFinite(a) || !Number.isFinite(b) || b < a) return null;
158	  return Math.round(((b - a) / 3600e3) * 10) / 10;
159	};
160	
161	// --- items nobody has moved --------------------------------------------------------
162	
163	// Open work items untouched for three days, split by WHO clears them. The split is the
164	// point: a person clears a park, and the janitor's leash clears the rest, so only the
165	// first half is a claim on the reader's morning.
166	export function stuckItems(reads, now, { days = STUCK_DAYS } = {}) {
167	  const cutoff = now - days * DAY_MS;
168	  const forYou = [];
169	  const onMachine = [];
170	  for (const read of reads) {
171	    for (const item of read.items ?? []) {
172	      if (item.state !== 'open' || !isQueueItem(item)) continue;
173	      const touched = ms(item.updated_at) ?? ms(item.created_at);
174	      if (touched === null || touched > cutoff) continue;
175	      (isParked(item) ? forYou : onMachine).push({ repo: read.repo, number: item.number, title: item.title });
176	    }
177	  }
178	  return { forYou, onMachine, total: forYou.length + onMachine.length };
179	}
180	
181	// --- work items closed with nobody in the loop -------------------------------------
182	
183	// The queue's own half of the autonomy figure: items that closed inside the window
184	// having never been parked. `outcomeOf` decides what closed, `isParked` what still
185	// wants a person — an item CLOSED while parked is one a person had to touch.
186	export function closedItems(reads, from, to) {
187	  let completed = 0;
188	  let unattended = 0;
189	  for (const read of reads) {
190	    for (const item of read.items ?? []) {
191	      if (item.state !== 'closed' || !isQueueItem(item)) continue;
192	      const day = (item.closed_at ?? '').slice(0, 10);
193	      if (!day || day < from || day > to) continue;
194	      const outcome = outcomeOf(item);
195	      if (outcome !== 'done' && outcome !== 'delivered') continue;
196	      completed += 1;
197	      if (!isParked(item)) unattended += 1;
198	    }
199	  }
200	  return { completed, unattended };
201	}
202	
203	// --- the block ---------------------------------------------------------------------
204	
205	// A figure, in the one shape the ledger renders: a value that may be null, the delta
206	// against the previous window, and whether that delta's own *bad when* rule fired.
207	//
208	// `bad` is passed in per figure rather than derived, because it is a JUDGEMENT stated
209	// in the page's spec — merged down while sessions are flat, stuck items rising — and
210	// the module that computes a number is not the one that decides it is worrying.
211	export function figure(value, previous, { unit, sub = null, spark = null, bad = false, gap = null } = {}) {
212	  return {
213	    value,
214	    previous: finite(previous),
215	    delta: value === null || finite(previous) === null ? null : value - previous,
216	    unit,
217	    sub,
218	    spark,
219	    bad: Boolean(bad) && value !== null,
220	    // What to say INSTEAD of the number when there is none. A gap is a sentence, never
221	    // a dash on its own: *not recorded* is information, an em dash is a puzzle.
222	    gap: value === null ? (gap ?? 'not recorded') : null,
223	  };
224	}
225	
226	// A 14-day series for one field, as the sparkline's two halves.
227	const sparkOf = (rows, field) => rows.map((r) => ({ day: r.day, value: finite(r[field]) }));
228	
229	export function fleetLedger(reads, { now, rates = null, windowDays = WINDOW_DAYS, days = LADDER_DAYS } = {}) {
230	  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);
231	  const folding = readable.filter((r) => r.usage);
232	  const rows = fleetDays(folding, { now, days });
233	  const w = windowsOf(rows, { now, windowDays });
234	
235	  const sum = (slice, field) => sumKnown(slice.map((r) => r[field]));
236	  const cur = (field) => sum(w.current, field);
237	  const prev = (field) => sum(w.previous, field);
238	
239	  const merged = mergedPrsIn(readable, w.current);
240	  const mergedPrev = mergedPrsIn(readable, w.previous);
241	  const closed = closedItems(readable, w.from, w.to);
242	  const closedPrev = closedItems(readable, w.prevFrom, w.prevTo);
243	  const stuck = stuckItems(readable, now);
244	
245	  const priced = priceWindow(w.current.flatMap((r) => r.tokensByModel), rates);
246	  const pricedPrev = priceWindow(w.previous.flatMap((r) => r.tokensByModel), rates);
247	
248	  const leads = (list, field) => list.map((p) => p[field]).filter((n) => finite(n) !== null);
249	  const issueLead = leads(merged, 'issueLeadHours');
250	  const issueLeadPrev = leads(mergedPrev, 'issueLeadHours');
251	  const sessionLead = leads(merged, 'sessionToMergeHours');
252	  const sessionLeadPrev = leads(mergedPrev, 'sessionToMergeHours');
253	
254	  const linesNet = (slice) => {
255	    const added = sum(slice, 'linesAdded');
256	    const removed = sum(slice, 'linesRemoved');
257	    return added === null || removed === null ? null : added - removed;
258	  };
259	  const releasedBy = [...new Set(w.current.flatMap((r) => r.releasedBy))].sort();
260	  const daysWithNone = w.current.filter((r) => !merged.some((p) => p.day === r.day)).length;
261	  const peakDay = w.current
262	    .map((r) => ({ day: r.day, n: merged.filter((p) => p.day === r.day).length }))
263	    .sort((a, b) => b.n - a.n || a.day.localeCompare(b.day))[0] ?? null;
264	
265	  const got = [
266	    figure(merged.length, mergedPrev.length, {
267	      unit: 'merged PRs',
268	      sub: `${closed.unattended} work items closed with nobody in the loop`,
269	      spark: sparkPairs(rows, (day) => merged.concat(mergedPrev).filter((p) => p.day === day).length),
270	      // Fewer merges while the sessions that produce them held up is something
271	      // stalling, which is the one reading of a down week that wants a person.
272	      bad: mergedPrev.length > 0 && merged.length < mergedPrev.length * 0.7
273	        && (cur('sessions') ?? 0) >= (prev('sessions') ?? 0) * 0.9,
274	    }),
275	    figure(cur('caught'), prev('caught'), {
276	      unit: 'caught before merge',
277	      sub: 'Stop hook blocked, agent fixed',
278	      spark: sparkOf(rows, 'caught'),
279	      // The win counter: bad only when it is ZERO while the checks were running, which
280	      // is enforcement silently off rather than a clean week.
281	      bad: cur('caught') === 0 && (cur('checkRuns') ?? 0) > 0,
282	    }),
283	    figure(cur('releases'), prev('releases'), {
284	      unit: 'releases',
285	      sub: releasedBy.length ? releasedBy.map(shortRepo).join(' · ') : 'none in the window',
286	      spark: sparkOf(rows, 'releases'),
287	    }),
288	    figure(linesNet(w.current), linesNet(w.previous), {
289	      unit: 'lines, net',
290	      sub: 'added − removed on the default branch',
291	      spark: null,
292	      gap: 'not recorded — no fold reaches the git history',
293	    }),
294	  ];
295	
296	  const cost = [
297	    figure(cur('tokensIn'), prev('tokensIn'), {
298	      unit: 'tokens in',
299	      sub: `${folding.length} of ${readable.length} folding · cache reads count as in`,
300	      spark: sparkOf(rows, 'tokensIn'),
301	      bad: (cur('tokensIn') ?? 0) > (prev('tokensIn') ?? 0) && merged.length < mergedPrev.length,
302	    }),
303	    figure(priced.usd === null ? null : Math.round(priced.usd), pricedPrev.usd === null ? null : Math.round(pricedPrev.usd), {
304	      unit: priced.ratesSet ? 'your rate table' : 'dollars',
305	      sub: pricingNote(priced),
306	      gap: priced.recorded
307	        ? (priced.ratesSet ? 'unpriced — no model in the window has a rate' : `unpriced — set \`${RATES_KEY}\` in this pack's config`)
308	        : 'not recorded — this fold predates tokensByModel',
309	    }),
310	    figure(cur('humanSeconds'), prev('humanSeconds'), {
311	      unit: 'yours',
312	      sub: `${fmtCount(cur('userMessages'))} turns · ${fmtCount(cur('sessions'))} sessions · gaps > 10m dropped`,
313	      spark: sparkOf(rows, 'humanSeconds'),
314	      bad: (cur('humanSeconds') ?? 0) > (prev('humanSeconds') ?? 0) && merged.length <= mergedPrev.length,
315	      gap: 'not recorded — this fold predates humanSeconds',
316	    }),
317	  ];
318	
319	  const mergedPerDay = w.current.length ? Math.round((merged.length / w.current.length) * 10) / 10 : null;
320	  const mergedPerDayPrev = w.previous.length ? Math.round((mergedPrev.length / w.previous.length) * 10) / 10 : null;
321	
322	  const speed = [
323	    figure(quantile(issueLead, 0.5), quantile(issueLeadPrev, 0.5), {
324	      unit: 'issue → merged',
325	      sub: `median · p90 ${fmtHours(quantile(issueLead, 0.9))}`,
326	      spark: null,
327	      // A lead time getting longer is a figure; half again as long, or a p90 past
328	      // three days, is the one a person acts on.
329	      bad: worseBy(quantile(issueLead, 0.5), quantile(issueLeadPrev, 0.5), 1.5) || (quantile(issueLead, 0.9) ?? 0) > 72,
330	      gap: 'not recorded — no merged PR named a closing issue',
331	    }),
332	    figure(quantile(sessionLead, 0.5), quantile(sessionLeadPrev, 0.5), {
333	      unit: 'session → merged',
334	      sub: `median · p90 ${fmtHours(quantile(sessionLead, 0.9))} · CI, then you`,
335	      spark: null,
336	      bad: (quantile(sessionLead, 0.5) ?? 0) > 4,
337	      gap: 'not recorded — this fold predates prs',
338	    }),
339	    figure(mergedPerDay, mergedPerDayPrev, {
340	      unit: 'merged / day',
341	      sub: peakDay && peakDay.n ? `peak ${peakDay.day} · ${daysWithNone} days with none` : `${daysWithNone} days with none`,
342	      spark: null,
343	    }),
344	    figure(stuck.total, null, {
345	      unit: `stuck ${STUCK_DAYS} d+`,
346	      sub: `${stuck.forYou.length} parked for you · ${stuck.onMachine.length} on the machine`,
347	      spark: null,
348	      // The one figure on the block whose bad-when is a level rather than a move: an
349	      // item parked for a person for three days is what feeds Start here.
350	      bad: stuck.forYou.length > 0,
351	    }),
352	  ];
353	
354	  return {
355	    window: { ...w, windowDays, folding: folding.length, members: readable.length, absent: readable.filter((r) => !r.usage).map((r) => r.repo).sort() },
356	    // The grid's rows with the ledger's columns rather than the queue's — the same
357	    // window, per member, so a fleet figure can be traced to the member carrying it.
358	    perMember: folding.map((r) => memberWindow(r, w)),
359	    days: rows,
360	    ledger: { got, cost, speed },
361	    totals: totalsOf({ merged, closed, priced, cur, stuck, rows: w.current }),
362	    merged,
363	    stuck,
364	    pricing: priced,
365	    pulse: pulseOf(rows, w),
366	  };
367	}
368	
369	// The three quotients under the double rule. Each is built from figures already on the
370	// block, so it introduces no source — and INHERITS BOTH GAPS: a numerator or
371	// denominator that is not recorded makes the quotient not recorded, rather than a
372	// confident number resting on a hole.
373	export function totalsOf({ merged, closed, priced, cur, stuck }) {
374	  const tokensIn = cur('tokensIn');
375	  const human = cur('humanSeconds');
376	  const agent = cur('agentSeconds');
377	  const per = (n, d) => (n === null || !d ? null : n / d);
378	  return {
379	    costPerMerged: priced.usd === null || !merged.length ? null : Math.round((priced.usd / merged.length) * 10) / 10,
380	    tokensPerMerged: per(tokensIn, merged.length),
381	    autonomy: closed.completed ? closed.unattended / closed.completed : null,
382	    humanToAgent: human === null || agent === null || !human ? null : Math.round(agent / human),
383	    caught: cur('caught'),
384	    stuckForYou: stuck.forYou.length,
385	  };
386	}
387	
388	// The 14-day session series, split into the two windows the identity draws in two
389	// weights, with today marked as its own state: it is not folded yet, and a dashed
390	// outline says so where a zero would say the fleet stopped.
391	export function pulseOf(rows, w) {
392	  const today = w.to;
393	  const days = rows.map((r) => ({
394	    day: r.day,
395	    sessions: r.sessions,
396	    members: r.movedBy,
397	    series: r.day === today ? 'today' : (r.day >= w.from ? 'current' : 'previous'),
398	  }));
399	  const known = days.map((d) => d.sessions).filter((n) => n !== null);
400	  const peak = known.length ? Math.max(...known) : null;
401	  const quiet = days.filter((d) => d.sessions === 0).map((d) => d.day);
402	  return { days, peak, quiet };
403	}
404	
405	// --- the sentences a figure carries -------------------------------------------------
406	
407	const shortRepo = (repo) => String(repo ?? '').split('/')[1] ?? repo;
408	
409	const worseBy = (now, before, factor) =>
410	  finite(now) !== null && finite(before) !== null && before > 0 && now > before * factor;
411	
412	const fmtCount = (n) => (n === null ? 'no' : String(n));
413	
414	export const fmtHours = (h) => {
415	  if (finite(h) === null) return 'not recorded';
416	  if (h < 1) return `${Math.round(h * 60)}m`;
417	  if (h < 48) return `${Math.round(h * 10) / 10}h`;
418	  return `${Math.round((h / 24) * 10) / 10} d`;
419	};
420	
421	// The dollar figure's own assumption, inline where the identity asks for it: whose
422	// rates, how concentrated the spend is, and how much of it nothing could price.
423	export function pricingNote(priced) {
424	  if (!priced.recorded) return 'no fold in the window carries a per-model split';
425	  if (!priced.ratesSet) return `no ${RATES_KEY} table configured · ${fmtTokens(priced.tokens)} unpriced`;
426	  const parts = [];
427	  if (priced.top) parts.push(`${Math.round(priced.top.share * 100)}% ${shortModel(priced.top.model)}`);
428	  parts.push(priced.unpricedTokens
429	    ? `${fmtTokens(priced.unpricedTokens)} unpriced (${priced.unpricedModels.map(shortModel).join(', ')})`
430	    : '0 unpriced');
431	  return parts.join(' · ');
432	}
433	
434	// A model id is a long word in a small step; the family is what a reader compares.
435	const shortModel = (id) => String(id ?? '').replace(/^claude-/, '').replace(/-\d{8}$/, '');
436	
437	export function fmtTokens(n) {
438	  if (finite(n) === null) return 'not recorded';
439	  if (n >= 1e9) return `${Math.round((n / 1e9) * 10) / 10}B`;
440	  if (n >= 1e6) return `${Math.round((n / 1e6) * 10) / 10}M`;
441	  if (n >= 1e3) return `${Math.round((n / 1e3) * 10) / 10}k`;
442	  return String(n);
443	}
444	
445	// Two 7-day halves of a per-day count the caller derives, in the sparkline's shape.
446	function sparkPairs(rows, countFor) {
447	  return rows.map((r) => ({ day: r.day, value: countFor(r.day) }));
448	}
449	
450	
451	// --- the machine --------------------------------------------------------------------
452	
453	// The scheduler's declared cadence, which every heartbeat square is judged against.
454	// Hourly is what the stub workflow fires at, and it is stated here rather than read
455	// per member because the stub is the same file in every repo.
456	export const SCHEDULER_CADENCE_MS = 3600e3;
457	
458	const level = (...verdicts) => ['critical', 'serious', 'you', 'machine', 'good'].find((l) => verdicts.includes(l)) ?? 'none';
459	
460	// How many members can be stale before it is the FLEET that has stopped updating rather
461	// than a few stragglers: the square root of its size (owner, 2026-09-07). It scales the
462	// way an alarm should — three of thirteen is a bad night, eight of thirteen is
463	// Claudinite itself not landing anywhere, and the two must not read alike.
464	const fleetWideBound = (total) => Math.sqrt(Math.max(0, total ?? 0));
465	
466	// A mount the nightly update has not landed on. `behind` and `behind-engine` are a
467	// converge that stopped moving; `unversioned` and `none` are one that never arrived at
468	// all, which is the worse case rather than an unreadable one.
469	const STALE_MOUNT = new Set(['behind', 'behind-engine', 'unversioned', 'none']);
470	
471	// Which stale member to name when only a few are: the one whose mount is furthest from
472	// the canon, since that is the one whose failure explains the rest.
473	const STALE_RANK = { none: 0, unversioned: 1, 'behind-engine': 2, behind: 3 };
474	
475	// The five cells, each already carrying its verdict and the one line naming the worst
476	// member — a name is what the reader acts on, where a count is something to go and
477	// look up. Except when the fault is the fleet's: past `fleetWideBound` the line names
478	// the count instead, because no single member is the thing to go and look at.
479	export function machinePanel(summaries, reads, { now, canon = null, strip = null } = {}) {
480	  // THE MACHINE IS THE AWAKE FLEET. A dormant member declared its scheduler stopped
481	  // (owner, 2026-09-13), so it is out of every cell here: it has no heartbeat to be
482	  // late, no mount anything will converge, and no anchor that will fire. Counting one
483	  // in a denominator makes an obedient repo read as a missing member.
484	  const all = (summaries ?? []).filter((s) => s?.status === 'adopted');
485	  const adopted = all.filter((s) => !s.dormant);
486	  const dormant = all.filter((s) => s.dormant).map((s) => s.repo);
487	
488	  // HEARTBEAT — one square per member, in the grid's own order.
489	  const beats = adopted.map((s) => {
490	    const last = s.runs?.lastAt ?? null;
491	    const age = last === null ? null : now - last;
492	    const verdict = !s.runs?.everRan ? 'critical' : (age > 2 * SCHEDULER_CADENCE_MS ? 'you' : 'good');
493	    return {
494	      repo: s.repo,
495	      age,
496	      level: verdict,
497	      title: `${shortRepo(s.repo)} — ${last === null ? 'never ran' : `${fmtAge(age)} ago${s.runs?.lastAtSource === 'folded' ? ', to the hour' : ''}`}`,
498	    };
499	  });
500	  const late = beats.filter((b) => b.level === 'you');
501	  const never = beats.filter((b) => b.level === 'critical');
502	  const heartbeat = {
503	    level: level(never.length ? 'critical' : null, late.length ? 'you' : null, 'good'),
504	    onTime: beats.length - late.length - never.length,
505	    total: beats.length,
506	    beats,
507	    note: [
508	      ...late.map((b) => `${shortRepo(b.repo)} ${fmtAge(b.age)} late`),
509	      ...never.map((b) => `${shortRepo(b.repo)} never`),
510	    ].join(' · ') || 'every member ran inside its cadence',
511	  };
512	
513	  // EXECUTOR — failures over the last 24 hours, fleet-wide, worst member named.
514	  const since = hourKeysSince(now, 24);
515	  const perMember = adopted.map((s) => {
516	    const read = (reads ?? []).find((r) => r?.repo === s.repo);
517	    const hours = since.map((h) => read?.usage?.hours?.[h]).filter(Boolean);
518	    return {
519	      repo: s.repo,
520	      failed: hours.reduce((n, h) => n + (h.failed ?? 0), 0),
521	      runs: hours.reduce((n, h) => n + (h.executor ?? 0), 0),
522	    };
523	  });
524	  const failed = perMember.reduce((n, m) => n + m.failed, 0);
525	  const worstExec = [...perMember].sort((a, b) => b.failed - a.failed)[0] ?? null;
526	  const executor = {
527	    level: level(failed >= 3 ? 'serious' : null, failed > 0 ? 'you' : null, 'good'),
528	    failed,
529	    runs: perMember.reduce((n, m) => n + m.runs, 0),
530	    inFlight: adopted.reduce((n, s) => n + (s.runs?.inFlight ?? 0), 0),
531	    note: failed && worstExec?.failed ? `worst ${shortRepo(worstExec.repo)}` : 'none failed',
532	  };
533	
534	  // FOLD AGE — the OLDEST member's stamp, since the block's every figure is only as
535	  // fresh as the stalest fold behind it.
536	  const stamps = (reads ?? [])
537	    .filter((r) => r?.usage?.generated)
538	    .map((r) => ({ repo: r.repo, age: now - (ms(r.usage.generated) ?? now) }));
539	  const oldest = [...stamps].sort((a, b) => b.age - a.age)[0] ?? null;
540	  const folding = (reads ?? []).filter((r) => r?.usage).length;
541	  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration).length;
542	  const foldAge = {
543	    level: oldest === null ? 'none' : (oldest.age > 6 * 3600e3 ? 'you' : 'good'),
544	    age: oldest?.age ?? null,
545	    note: `${folding} of ${readable} fold`,
546	    worst: oldest?.repo ?? null,
547	  };
548	
549	  // UPDATES — the members Claudinite's own nightly update did not land on, and the
550	  // band's TOP SIGNAL (owner, 2026-09-07): a fleet whose mounts have stopped moving is
551	  // the whole machine failing, where a late scheduler or a failed executor run is one
552	  // member having a bad hour. Judged on the outcome — the stamp — whatever stopped it,
553	  // since the stamp is what every member reports and it cannot report a landing that
554	  // did not happen. Unknown with no canon configured, and unknown is SAID rather than
555	  // read as current.
556	  const stale = [...adopted.filter((s) => STALE_MOUNT.has(s.mount?.state))]
557	    .sort((a, b) => STALE_RANK[a.mount.state] - STALE_RANK[b.mount.state]);
558	  const fleetWide = Boolean(canon) && stale.length > fleetWideBound(adopted.length);
559	  const updates = {
560	    level: canon ? level(fleetWide ? 'critical' : null, stale.length ? 'you' : null, 'good') : 'none',
561	    stale: canon ? stale.length : null,
562	    total: adopted.length,
563	    fleetWide,
564	    note: !canon ? 'unknown — no canonRepo configured'
565	      : fleetWide ? `${stale.length} of ${adopted.length} members are not on the current mount`
566	        : stale.length ? `${shortRepo(stale[0].repo)} worst` : 'every mount current',
567	  };
568	
569	  // NEXT WAKE — when the fleet next acts, and the 24-hour strip behind it.
570	  //
571	  // A NAMED GAP RATHER THAN AN EMPTY STRIP where no roster reached this page. An
572	  // anchor comes from a task's own declaration, and the fleet sweep reads each
573	  // member's task PATHS (that is what `declaredTasks` counts) but not their contents —
574	  // reading them would be one content request per task per member, which is the one
575	  // property this whole block is built not to spend. An empty strip would read as
576	  // "nothing wakes", which is the serious verdict; the absence has to say it is an
577	  // absence.
578	  const declaring = adopted.filter((s) => (s.declaredTasks ?? 0) > 0).length;
579	  const nextHour = strip?.hours?.find((h) => h.tasks.length) ?? null;
580	  const wake = strip === null
581	    ? {
582	      level: 'none', at: null, members: 0, tasks: 0, read: false,
583	      note: declaring
584	        ? `not read — ${declaring} member(s) declare tasks, their anchors are in declarations this page does not fetch`
585	        : 'not read — no roster reached this page',
586	    }
587	    : {
588	      level: !strip.peak && declaring ? 'serious' : (strip.hours.some((h) => h.held) ? 'critical' : 'good'),
589	      at: nextHour?.hour ?? null,
590	      members: nextHour ? new Set(nextHour.tasks.map((t) => t.repo).filter(Boolean)).size : 0,
591	      tasks: nextHour?.tasks.length ?? 0,
592	      read: true,
593	      note: !strip.peak
594	        ? (declaring ? `${declaring} member(s) declare tasks and nothing wakes in 24 h` : 'no task declares an anchor')
595	        : `${strip.hours.reduce((n, h) => n + h.tasks.length, 0)} wakes in 24 h`,
596	    };
597	
598	  // Named rather than merely absent: the reader is told the panel is about the awake
599	  // fleet, and which members it left alone.
600	  return { updates, heartbeat, executor, foldAge, wake, dormant };
601	}
602	
603	// The last N whole UTC hours, as the fold's own hour keys.
604	export function hourKeysSince(now, hours) {
605	  return Array.from({ length: hours }, (_, i) =>
606	    new Date(now - i * 3600e3).toISOString().slice(0, 13));
607	}
608	
609	export function fmtAge(msVal) {
610	  if (finite(msVal) === null) return 'never';
611	  if (msVal < 60e3) return '<1m';
612	  if (msVal < 3600e3) return `${Math.round(msVal / 60e3)}m`;
613	  if (msVal < 86400e3) return `${Math.floor(msVal / 3600e3)}h ${Math.round((msVal % 3600e3) / 60e3)}m`;
614	  return `${Math.floor(msVal / 86400e3)}d`;
615	}
616	
617	
618	// One member's own share of the window. Every field is `null` where that member's fold
619	// could not answer, never 0: a member folding without token records is a different row
620	// from one that spent nothing.
621	export function memberWindow(read, w) {
622	  const rows = w.current.map((d) => read.usage?.days?.[d.day]).filter(Boolean);
623	  const sum = (field) => sumKnown(rows.map((row) => row[field]));
624	  const scopes = rows.flatMap((row) => Object.values(row.checks ?? {}));
625	  return {
626	    repo: read.repo,
627	    sessions: sum('sessions'),
628	    turns: sum('userMessages'),
629	    tokensIn: sum('tokensIn'),
630	    caught: scopes.length ? scopes.reduce((n, s) => n + (s.failures ?? 0) + (s.ciFailures ?? 0), 0) : null,
631	  };
632	}
633

