1	// The Work board's explore panels — one per status, because the reader's next move
2	// differs by status ([docs/work-board.md](../../docs/work-board.md), *The explore panel*).
3	//
4	// EVERY PANEL ENDS IN `do`: one imperative. A panel that only describes is a longer
5	// hover; the point of opening one is to know what to do next.
6	//
7	// EVERY FIELD NAMES ITS SOURCE, and a field this page cannot read says *not read*
8	// rather than being left out — a missing row and an unreadable one are different facts,
9	// and only the second is worth a reader's attention. The size of a PR, the checks on
10	// its head sha and the drain tick's hour are all *not read* here by design: each costs
11	// a request per mark, and the board is built not to spend one.
12	//
13	// Pure. The comments a panel quotes are fetched by the view and handed in; nothing here
14	// performs I/O, so every panel is a function of what was read.
15	
16	import {
17	  parseWorkItemBody, parseWorkItemTitle, statusOf, labelNames, outcomeOf,
18	} from '../../../claudinite-tasks/public/work-item-grammar.mjs';
19	import {
20	  PARK_PREFIX, CLAIM_MARKER, HANDOFF_MARKER,
21	} from '../../../claudinite-tasks/public/task-constants.mjs';
22	import { holdsOnFailure } from './task-calendar.mjs';
23	
24	const NOT_READ = 'not read';
25	const ms = (t) => (t == null ? null : new Date(t).getTime());
26	const stamp = (t) => (t ? new Date(t).toISOString().replace('T', ' ').slice(0, 16) : NOT_READ);
27	const days = (from, to) => (from == null || to == null ? null : Math.round((to - from) / 86400e3));
28	
29	// One field of a panel. `value` may be null, and then `note` says why — which is what
30	// keeps *not read* and *nothing there* apart on the page.
31	const field = (label, value, note = null) => ({ label, value: value ?? null, note: value == null ? (note ?? NOT_READ) : note });
32	
33	// The command `converge-item.mjs` would print for this item, spelled exactly as its own
34	// usage block spells it — so a reader can paste it, and so this page and the queue
35	// cannot drift about what converging one item takes.
36	export function convergeCommand(item, repo, outcome = 'done') {
37	  return `node .claudinite/shared/packs/claudinite-tasks/queue/converge-item.mjs \\\n`
38	    + `  --issue ${item.number} --outcome ${outcome} --summary "<what happened>" \\\n`
39	    + `  --repo ${repo} --item-file <the issue as JSON>`;
40	}
41	
42	// Which panel a mark opens. The board's own row kinds, mapped to the six the spec
43	// names — a park splits by kind because an approval IS its PR and the other three are
44	// a question waiting for an answer.
45	export function panelKind(row) {
46	  if (row.kind === 'pr') return 'pending-pr';
47	  if (row.kind === 'task') return 'scheduled-task';
48	  if (row.parkKind === 'failure') return 'failed-task';
49	  if (row.parkKind === 'approval') return 'pending-pr';
50	  if (row.parkKind) return 'park';
51	  if (row.kind === 'issue') return 'plain-issue';
52	  return 'stuck-item';
53	}
54	
55	// --- the six panels -------------------------------------------------------------------
56	
57	export function pendingPrPanel(row, { item, declaration, repo, prs = [], items = [], comments = null }) {
58	  const body = item ? parseWorkItemBody(item.body) : null;
59	  const converge = comments?.find((c) => /AUTOMERGE:/i.test(c.body ?? ''));
60	  const closes = row.closesIssue ?? (item?.number ?? null);
61	  const unblocks = items.filter((i) => i.state === 'open' && parseWorkItemBody(i.body).blockedBy.includes(closes));
62	  return {
63	    kind: 'pending-pr',
64	    title: `${row.gutter} — ${row.title}`,
65	    fields: [
66	      field('waits for', row.waits
67	        ? row.why
68	        : (converge ? `the run said: ${firstLine(converge.body)}` : null),
69	      row.waits ? null : 'the run\'s own AUTOMERGE verdict is in a comment this page has not fetched'),
70	      field('policy', declaration?.automerge ?? body?.merge ?? null, 'neither the task declaration nor the item carries a merge policy'),
71	      field('closes / ends', closes ? `#${closes}${body?.endsWhen ? ` · ends when #${body.endsWhen} closes` : ''}` : null,
72	        'this PR names no closing issue in its body'),
73	      field('unblocks', unblocks.length ? unblocks.map((i) => `#${i.number}`).join(', ') : null,
74	        'nothing open is Blocked-by what this closes'),
75	      // Two facts that each cost a request per mark; the board is built not to spend
76	      // one, so they are stated as unread rather than quietly omitted.
77	      field('size · CI', null, 'not read — the PR page and its head sha\'s checks are a request each'),
78	      field('left by', runRecord(comments), comments ? 'no claim or hand-off comment on the item' : 'the item\'s comments have not been fetched'),
79	    ],
80	    do: row.waits
81	      ? `Review and merge ${row.gutter}, or give its item an Automerge policy.`
82	      : `Nothing to do — it lands itself. Watch ${row.gutter} for CI.`,
83	  };
84	}
85	
86	export function failedTaskPanel(row, { item, repo, siblings = [], declaration = null, comments = null }) {
87	  const later = siblings
88	    .filter((i) => i.state === 'closed' && ms(i.closed_at) > ms(item?.created_at))
89	    .map((i) => `#${i.number} ${outcomeOf(i) ?? 'no outcome'}`);
90	  // No park holds a lane by itself: the declaration's own `last-run-not-failed` is
91	  // what stops a task past its failure, so the lane field reads the declaration —
92	  // and says so when it could not.
93	  const holds = Array.isArray(declaration?.preconditions) ? holdsOnFailure(declaration.preconditions) : null;
94	  const lane = holds === null ? null
95	    : !holds ? 'open — this declaration does not hold its lane on a failure, so the task is asked on schedule around the park'
96	      : later.length
97	        ? `the roster says this lane is HELD, and ${later.length} later occurrence(s) closed anyway: ${later.slice(0, 4).join(', ')}`
98	        : 'held — nothing new is scheduled for this task until it clears';
99	  return {
100	    kind: 'failed-task',
101	    title: `${row.gutter} — ${row.title}`,
102	    fields: [
103	      field('last run', runRecord(comments), comments ? 'no claim or hand-off comment on the item' : 'the item\'s comments have not been fetched'),
104	      field('what broke', comments ? firstLine(comments.find((c) => /converge|failed|error/i.test(c.body ?? ''))?.body) : null,
105	        comments ? 'no converge comment on the item' : 'the item\'s comments have not been fetched'),
106	      field('park history', comments ? janitorRules(comments).join(' · ') || null : null,
107	        comments ? 'no janitor rule comment on the item' : 'the item\'s comments have not been fetched'),
108	      // THE CONTRADICTION THIS PANEL EXISTS FOR: a declaration that holds its lane on
109	      // a failure, and later closed items of the same task as the record disagreeing.
110	      field('lane', lane, 'the task declaration has not been read — only its own `last-run-not-failed` holds a lane'),
111	    ],
112	    do: `Diagnose, then converge it:\n${convergeCommand(item ?? { number: row.gutter.replace('#', '') }, repo, 'done')}`,
113	  };
114	}
115	
116	export function stuckItemPanel(row, { item, repo, items = [], prs = [], comments = null }) {
117	  const body = item ? parseWorkItemBody(item.body) : { blockedBy: [], notBefore: null, merge: null };
118	  const byNumber = new Map(items.map((i) => [i.number, i]));
119	  const chain = body.blockedBy.map((n) => {
120	    const blocker = byNumber.get(n);
121	    const pr = prs.find((p) => p.closesIssue === n && !p.merged_at);
122	    const mover = pr ? `PR #${pr.number} closes it when you merge` : (blocker && parseWorkItemTitle(blocker.title) ? 'its own task' : 'nobody');
123	    return `#${n} ${blocker ? (blocker.state === 'open' ? 'open' : 'closed') : NOT_READ} — moved by ${mover}`;
124	  });
125	  return {
126	    kind: 'stuck-item',
127	    title: `${row.gutter} — ${row.title}`,
128	    fields: [
129	      field('the chain', chain.length ? chain.join('\n') : null, 'this item is Blocked-by nothing'),
130	      field('placed at', row.at ? stamp(row.at) : null, row.why),
131	      field('the premise', item ? `filed ${stamp(item.created_at)} · ${days(ms(item.created_at), Date.now())} d old` : null),
132	      field('landing', body.merge ?? null, 'no Merge policy — its PR will wait for a person'),
133	      field('janitor', comments ? janitorRules(comments).join(' · ') || null : null,
134	        comments ? 'no janitor comment on the item' : 'the item\'s comments have not been fetched'),
135	    ],
136	    do: row.broken
137	      ? `Close #${row.blocker}, give it a task, or re-scope ${row.gutter} so it no longer waits on it.`
138	      : `Leave it — a future Not-before is the mechanism working. Re-scope only if the premise has moved.`,
139	  };
140	}
141	
142	export function plainIssuePanel(row, { item, items = [], prs = [], now }) {
143	  const blocks = items.filter((i) => parseWorkItemBody(i.body).blockedBy.includes(item?.number));
144	  const labels = item ? labelNames(item) : [];
145	  const idle = days(ms(item?.updated_at), now);
146	  return {
147	    kind: 'plain-issue',
148	    title: `${row.gutter} — ${row.title}`,
149	    fields: [
150	      field('age · idle', item ? `${days(ms(item.created_at), now)} d old · idle ${idle} d` : null),
151	      field('blocks', blocks.length ? blocks.map((i) => `#${i.number}`).join(', ') : null, 'nothing is Blocked-by it'),
152	      field('who moves it', prs.some((p) => p.closesIssue === item?.number)
153	        ? `PR #${prs.find((p) => p.closesIssue === item.number).number}`
154	        : null,
155	      'no queue mark, no Task: field, and no open PR closes it — nothing scheduled will touch it'),
156	      field('rot', idle >= 14 ? `idle ${idle} d, past the 14 d bar` : `idle ${idle} d`),
157	      field('quick-win', labels.includes('quick-win')
158	        ? (blocks.length ? `yes — closing it releases ${blocks.length} row(s)` : 'yes — and it unblocks nothing')
159	        : null, 'not labelled quick-win'),
160	    ],
161	    do: blocks.length
162	      ? `Close ${row.gutter} — ${blocks.length} row(s) are waiting behind it.`
163	      : `Decide: close it, label it quick-win, or let it rot knowingly.`,
164	  };
165	}
166	
167	export function scheduledTaskPanel(row, { siblings = [], declaration = null, cost = null }) {
168	  const recent = siblings
169	    .filter((i) => i.state === 'closed')
170	    .sort((a, b) => ms(b.closed_at) - ms(a.closed_at))
171	    .slice(0, 8)
172	    .map((i) => `${(i.closed_at ?? '').slice(5, 10)} ${outcomeOf(i) ?? 'none'}`);
173	  return {
174	    kind: 'scheduled-task',
175	    title: row.task ?? row.key,
176	    fields: [
177	      field('last occurrences', recent.length ? recent.join(' · ') : null, 'no closed occurrence in the window'),
178	      field('next anchor', row.row?.nextAsk?.at ? stamp(row.row.nextAsk.at) : null, row.row?.anchorNote ?? 'no anchor — the declaration names no cadence'),
179	      field('model', declaration?.agent_model ?? 'none · code-work'),
180	      field('expected outcome', declaration?.expected_outcome ?? null, 'the declaration names none'),
181	      field('automerge', declaration?.automerge ?? null, 'the declaration names none — its PRs wait for a person'),
182	      field('cost per run', cost && cost.sessions ? `${Math.round((cost.tokensIn ?? 0) / cost.sessions).toLocaleString('en-US')} tok/session` : null,
183	        'this fold carries no per-task cost yet'),
184	    ],
185	    do: 'Nothing — it is scheduled. Change its cadence or model in its own task.json.',
186	  };
187	}
188	
189	export function parkPanel(row, { item, repo, comments = null }) {
190	  const body = item ? parseWorkItemBody(item.body) : {};
191	  return {
192	    kind: 'park',
193	    title: `${row.gutter} — ${row.title}`,
194	    fields: [
195	      field('the ask', comments ? firstLine(comments[comments.length - 1]?.body) : null,
196	        comments ? 'the item carries no comment stating the ask' : 'the item\'s comments have not been fetched'),
197	      field('kind', row.parkKind ? `needs-human-${row.parkKind}` : null),
198	      // The one thing that would close this without a person, if it exists.
199	      field('would close itself when', body.endsWhen ? `#${body.endsWhen} closes` : null,
200	        'no Ends-when condition — only a person clears this'),
201	    ],
202	    do: `Answer it, then converge:\n${convergeCommand(item ?? { number: 0 }, repo, row.parkKind === 'approval' ? 'done' : row.parkKind ?? 'done')}`,
203	  };
204	}
205	
206	// --- the run record a panel quotes ------------------------------------------------------
207	
208	// The claim → hand-off → converge beats, from the markers the queue's own protocol
209	// writes. Read from the item's comments, which the view fetches for the opened mark.
210	export function runRecord(comments) {
211	  if (!comments) return null;
212	  const beat = (marker, name) => {
213	    const hit = comments.find((c) => (c.body ?? '').includes(marker));
214	    return hit ? `${name} ${stamp(hit.created_at)}` : null;
215	  };
216	  const beats = [beat(CLAIM_MARKER, 'claimed'), beat(HANDOFF_MARKER, 'handed off')].filter(Boolean);
217	  return beats.length ? beats.join(' → ') : null;
218	}
219	
220	// The janitor names its own rule in the comment it leaves, which is what makes a park's
221	// history readable at all.
222	export const janitorRules = (comments) => (comments ?? [])
223	  .filter((c) => /janitor|rule [A-H]\b/i.test(c.body ?? ''))
224	  .map((c) => firstLine(c.body));
225	
226	const firstLine = (body) => {
227	  const line = String(body ?? '').split('\n').map((l) => l.replace(/<!--.*?-->/g, '').trim()).find(Boolean);
228	  return line ? line.slice(0, 200) : null;
229	};
230	
231	// --- the whole panel --------------------------------------------------------------------
232	
233	export function buildPanel(row, context) {
234	  switch (panelKind(row)) {
235	    case 'pending-pr': return pendingPrPanel(row, context);
236	    case 'failed-task': return failedTaskPanel(row, context);
237	    case 'scheduled-task': return scheduledTaskPanel(row, context);
238	    case 'plain-issue': return plainIssuePanel(row, context);
239	    case 'park': return parkPanel(row, context);
240	    default: return stuckItemPanel(row, context);
241	  }
242	}
243

