1	// The dashboard's derivation layer — repo facts in, view rows out. Pure: it reads
2	// no clock, opens no socket, and touches no DOM, so the whole of what the page
3	// claims is testable in Node and shared verbatim with the browser.
4	//
5	// It states NONE of the queue's vocabulary itself. The label set, the title
6	// grammar, the leash constants and the anchor arithmetic are imported from the
7	// engine modules that define them, which is what makes a dashboard that cannot
8	// drift from the mechanism it renders: there is no second copy to drift.
9	//
10	// Those engine modules are pure ESM with no `node:` imports, which is the property
11	// this file depends on and `browser-graph.test.mjs` pins across the page's whole
12	// import graph. Living inside `packs/claudinite-tasks/` makes the queue modules siblings,
13	// so the dashboard sits beside the mechanism it renders rather than reaching across
14	// the tree at it.
15	
16	import { parseTaskDeclaration, applyTaskDefaults } from './declaration-text.mjs';
17	import {
18	  mostRecentAnchor, nextAnchor, periodMs, taskPeriodMs, cadenceOf, cadenceTermFor, holdsOnFailure, holdsOnAnyPark, statesConditions,
19	  DUE_TERM, ELAPSED_TERM,
20	} from './task-calendar.mjs';
21	import {
22	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
23	} from '../../../claudinite-tasks/public/task-constants.mjs';
24	import {
25	  WORK_PREFIX, STATUS_BLOCKED, STATUS_READY, URGENT, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, 
26	  STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_DECISION,
27	  STATUS_NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_FAILURE, CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
28	} from '../../../claudinite-tasks/public/task-constants.mjs';
29	import {
30	  outcomeOf as decodeOutcome, statusesOn, isParked, parkKindOf, triageLabelFor, isBlockingPark,
31	  parseLastVerdict, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, hasLabel, labelNames,
32	} from '../../../claudinite-tasks/public/work-item-grammar.mjs';
33	
34	export {
35	  WORK_PREFIX, STATUS_BLOCKED, STATUS_READY, URGENT, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
36	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STUCK_BLOCKED_MS, STALE_READY_PERIODS,
37	  parseWorkItemTitle, nextAnchor, mostRecentAnchor, periodMs,
38	};
39	
40	// How long a due item may sit blocked before the page calls the scheduler run out. The scheduler run
41	// is the repo's one cron, hourly; two fires of slack keeps a single late fire from
42	// reading as a fault. Not an engine constant because nothing engine-side measures
43	// this — the scheduler run readies due items on its next fire, whenever that is.
44	export const DUE_SLACK_MS = 2 * 3600e3;
45	
46	const ms = (t) => (t == null ? null : new Date(t).getTime());
47	
48	// --- where a declared pack's tasks live ---------------------------------------
49	
50	// A pack contributes tasks only if the repo DECLARES it: presence on disk is not
51	// activation (core's rule), and the mount carries packs a repo never declared. So
52	// the roster is built from the declaration list, and a task directory belonging to
53	// an undeclared pack is skipped rather than rendered greyed-out.
54	//
55	// Two roots, because the same code reads the canon home and a member: the home
56	// runs from the repo root (`packs/<id>`), a member from the mount
57	// (`.claudinite/shared/packs/<id>`), and a local pack — declared `local/<name>` —
58	// from `../../.claudinite/local/packs/<name>` in both.
59	export function declaredPackDirs(config) {
60	  const dirs = new Map();
61	  for (const entry of config?.packs ?? []) {
62	    const id = typeof entry === 'string' ? entry : entry?.id;
63	    if (!id) continue;
64	    if (id.startsWith('local/')) {
65	      const name = id.slice('local/'.length);
66	      dirs.set(id, [`.claudinite/local/packs/${name}`]);
67	    } else {
68	      dirs.set(id, [`packs/${id}`, `.claudinite/shared/packs/${id}`]);
69	    }
70	  }
71	  return dirs;
72	}
73	
74	const TASK_PATH_RE = /^(.*)\/tasks\/([^/]+)\/task\.json$/;
75	
76	// Every declared pack's task declarations, from one recursive tree listing.
77	// `paths` is the flat list of blob paths the tree API returned.
78	export function taskDeclarationPaths(paths, config) {
79	  const dirs = declaredPackDirs(config);
80	  const found = [];
81	  for (const path of paths ?? []) {
82	    const m = TASK_PATH_RE.exec(path);
83	    if (!m) continue;
84	    const [, packDir, task] = m;
85	    for (const [pack, roots] of dirs) {
86	      if (roots.includes(packDir)) found.push({ pack, task, path });
87	    }
88	  }
89	  return found.sort((a, b) => `${a.pack}/${a.task}`.localeCompare(`${b.pack}/${b.task}`));
90	}
91	
92	// --- reading a task declaration -----------------------------------------------
93	
94	// The page reads a declaration as TEXT: it renders other repos over the API, where
95	// there is nothing to import and no Node to import it with. A `task.json` parses
96	// whole and takes the contract's defaults for the fields it omits — the same
97	// door the engine's loader runs it through.
98	//
99	// A field this cannot read comes back NULL and renders as "unknown". It is never
100	// defaulted: a task whose declaration this misreads must look unreadable, because a
101	// plausible wrong cadence would silently move a next-anchor the whole roster is
102	// read for. An ABSENT `preconditions` is not an unread one: a declaration that was
103	// read and carries no key requires nothing, exactly as its author wrote it, and
104	// reads as `[]`. An absent `trigger` is not unread either — it is derived, as the
105	// contract's own door derives it.
106	
107	// THE FREQUENCY DOOR, as the page runs it (#1725). `frequency` is retired: a task's
108	// cadence is a term in its own `preconditions`. A declaration still carrying the
109	// field — another repo's, read over the API — reads as the cadence term it always
110	// meant, first in the list, with the `none` it used to need beside it dropped; the
111	// field itself does not survive, and nothing downstream reads it. This is the
112	// contract's own rule (`normalizeTaskDeclaration` in `task-contract.mjs`), spelled
113	// again through the same `cadenceTermFor` because that module reaches into `node:`
114	// builtins the page cannot load; `model.test.mjs` runs both over one vector set so
115	// the two cannot drift apart unseen. `manual` meant no schedule and adds no term
116	// (`cadenceTermFor` answers null for it), so what stood beside it is the whole
117	// expression; nothing here writes the old word.
118	const NONE = 'none';
119	// THE TRIGGER DOOR, as the page runs it (#1725). `trigger` says whether the
120	// scheduler asks a task; a declaration written before the field is read off the
121	// shape of its conditions, exactly as the contract's door reads it. The one thing
122	// the page cannot do is resolve a task's OWN terms, so a legacy declaration whose
123	// condition reads the item itself is read here as scheduled — the engine's own door
124	// is handed those terms and is not; no canon declaration is in that state, and one
125	// stating its trigger never reaches this branch at all.
126	export const TRIGGER_SCHEDULE = 'schedule';
127	export const TRIGGER_REQUEST = 'request';
128	const withTrigger = (trigger, preconditions) => {
129	  if (trigger === TRIGGER_SCHEDULE || trigger === TRIGGER_REQUEST) return trigger;
130	  if (!Array.isArray(preconditions)) return null;
131	  return statesConditions(preconditions) ? TRIGGER_SCHEDULE : TRIGGER_REQUEST;
132	};
133	function withCadenceTerm(frequency, preconditions) {
134	  if (frequency == null) return preconditions;
135	  const term = cadenceTermFor(frequency);
136	  const stated = (preconditions ?? []).filter((c) => String(c).trim() !== NONE);
137	  return term === null || stated.some((c) => String(c).trim() === term) ? stated : [term, ...stated];
138	}
139	
140	// A task may decline to run; whether it CAN is the difference between "did not run"
141	// being routine and being a fault, so the roster shows it. The cadence terms say WHEN
142	// a task runs, not whether, and `none` is the EMPTY precondition — so neither is a
143	// gate, and a task carrying only those answers no here, exactly as it should.
144	const CADENCE_TERM_NAMES = [DUE_TERM, ELAPSED_TERM];
145	const termName = (t) => t.split(':')[0].trim();
146	const isGate = (entry) => String(entry ?? '').split('||')
147	  .some((t) => termName(t) !== NONE && !CADENCE_TERM_NAMES.includes(termName(t)));
148	const hasGate = (preconditions) => (preconditions ?? []).some(isGate);
149	
150	// The fields the roster reads, and only those, so a declaration carrying more
151	// renders the same as one carrying exactly these. Unparseable text reads as every
152	// field unknown.
153	export function parseDeclaration(text) {
154	  let decl;
155	  try {
156	    decl = parseTaskDeclaration(String(text ?? ''));
157	  } catch {
158	    decl = null;
159	  }
160	  const read = decl !== null && typeof decl === 'object' && !Array.isArray(decl);
161	  if (read) applyTaskDefaults(decl); else decl = {};
162	  const scalarOf = (v) => (['string', 'number', 'boolean'].includes(typeof v) ? v : null);
163	  // On a declaration that parsed, an absent `preconditions` is the empty expression;
164	  // one present but not a list of strings was not read, and neither was anything on
165	  // text that did not parse.
166	  const stated = !read ? null
167	    : decl.preconditions === undefined ? []
168	      : Array.isArray(decl.preconditions) && decl.preconditions.every((c) => typeof c === 'string') ? decl.preconditions : null;
169	  const preconditions = withCadenceTerm(scalarOf(decl.frequency), stated);
170	  return {
171	    id: scalarOf(decl.id),
172	    trigger: withTrigger(scalarOf(decl.trigger), preconditions),
173	    agent_model: scalarOf(decl.agent_model),
174	    expected_outcome: scalarOf(decl.expected_outcome),
175	    interrupt_policy: scalarOf(decl.interrupt_policy),
176	    code_work: scalarOf(decl.code_work),
177	    agent_execution_timeout: scalarOf(decl.agent_execution_timeout),
178	    preconditions,
179	    has_precondition: hasGate(preconditions),
180	  };
181	}
182	
183	// --- a task's cadence ------------------------------------------------------------
184	
185	// What a declaration says about WHEN its task runs, in the roster's terms: one
186	// display word, the period the task keeps, and whether the scheduler asks it at all.
187	// Two fields answer that, as they do for the scheduler — `trigger` says whether the
188	// task is asked, `cadenceOf` says how often it may then say yes — and four answers
189	// stay apart: a cadence; NO cadence term, a task asked at every tick that runs on
190	// its other conditions; a REQUEST task, which the scheduler never asks and which
191	// runs only from an item somebody creates (a mark, a wake, a chain link); and
192	// UNREADABLE, a declaration this could not lift — because a parse failure shown as
193	// "on movement" would hide behind a legitimate answer, and a task that reads exactly
194	// as its author wrote it must not show as unknown.
195	//
196	// Only a `due:` cadence is on the calendar, so only it can have a next anchor: an
197	// elapsed cadence counts from the task's newest run, and no-cadence and off-schedule
198	// have no next instant at all. `scheduled` is null, not false, where nothing was read.
199	//
200	// `holdsOnFailure` is the same read for the one other thing a declaration says about
201	// its own lane: whether a failure park stops the task (`last-run-not-failed`). No
202	// park holds a lane by itself, so a failure the declaration does not name is a break
203	// to diagnose beside a task still being asked on schedule.
204	export function describeCadence(preconditions, trigger) {
205	  if (!Array.isArray(preconditions)) {
206	    return { frequency: null, cadence: null, periodMs: null, scheduled: null, holdsOnFailure: null, holdsOnAnyPark: null, anchorNote: 'cadence unknown' };
207	  }
208	  const holds = holdsOnFailure(preconditions);
209	  const holdsAnywhere = holdsOnAnyPark(preconditions);
210	  // The door once more, so a caller handing over only the conditions — a fixture, a
211	  // declaration written before the field — reads exactly as the roster's own entry does.
212	  if (withTrigger(trigger, preconditions) !== TRIGGER_SCHEDULE) {
213	    return { frequency: 'unscheduled', cadence: null, periodMs: null, scheduled: false, holdsOnFailure: holds, holdsOnAnyPark: holdsAnywhere, anchorNote: 'not on the schedule — runs only from an item somebody creates' };
214	  }
215	  const cadence = cadenceOf(preconditions);
216	  const period = taskPeriodMs({ preconditions });
217	  if (cadence === null) {
218	    return { frequency: 'on movement', cadence, periodMs: period, scheduled: true, holdsOnFailure: holds, holdsOnAnyPark: holdsAnywhere, anchorNote: 'no cadence term — asked at every tick' };
219	  }
220	  if (cadence.kind === 'elapsed') {
221	    return {
222	      frequency: `every ${cadence.text}`, cadence, periodMs: period, scheduled: true, holdsOnFailure: holds, holdsOnAnyPark: holdsAnywhere,
223	      anchorNote: `every ${cadence.text} — counted from its newest run, not the calendar`,
224	    };
225	  }
226	  return { frequency: cadence.cadence, cadence, periodMs: period, scheduled: true, holdsOnFailure: holds, holdsOnAnyPark: holdsAnywhere, anchorNote: null };
227	}
228	
229	// --- work items ----------------------------------------------------------------
230	
231	// An item is a filed `[claudinite-work]` issue OR an adopted marked issue — the
232	// one-issue request model's other shape, which keeps the person's own title
233	// One definition, shared with the queue's own reader.
234	export { isQueueItem as isWorkItem } from '../../../claudinite-tasks/public/work-item-grammar.mjs';
235	
236	// THE PAGE'S FIVE STATE KEYS. Four are the engine's own status labels; the fifth is
237	// this page's own word, because a park is four labels and the page groups them into
238	// one column, routing by kind separately (`triageOf`). It is a display key and never
239	// a label: nothing writes `parked` to an issue.
240	const STATE_KEY = new Map([
241	  [STATUS_BLOCKED, STATUS_BLOCKED], [STATUS_READY, STATUS_READY],
242	  [STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_EXECUTOR], [STATUS_RUNNING_AGENT, STATUS_RUNNING_AGENT],
243	]);
244	
245	// The one state an open item is in, decoded from whatever spelling filed it, or
246	// `unlabelled` for an item wearing none — which is not a display quirk but the
247	// torn-label-swap leavings the janitor repairs, so it gets its own rendered state
248	// rather than being folded into "blocked".
249	export const PARKED = 'parked';
250	
251	export function stateOf(item) {
252	  if (item?.state === 'closed') return 'closed';
253	  if (isParked(item)) return PARKED;
254	  const worn = statusesOn(item).filter((s) => STATE_KEY.has(s));
255	  if (worn.length === 1) return STATE_KEY.get(worn[0]);
256	  if (worn.length > 1) return 'torn';
257	  return 'unlabelled';
258	}
259	
260	// What the park is asking for, or null for an item that is not parked. A park whose
261	// kind cannot be decoded — an older engine's bare one, a word a newer engine
262	// invented — reads as `failure`, the lane that says "someone diagnose this".
263	export const triageOf = (item) => (isParked(item) ? triageLabelFor(parkKindOf(item)) : null);
264	
265	const TRIAGE_TEXT = {
266	  [STATUS_NEEDS_HUMAN_APPROVAL]: 'a PR to approve',
267	  [STATUS_NEEDS_HUMAN_ACTION]: 'something to change outside the code',
268	  [STATUS_NEEDS_HUMAN_DECISION]: 'a decision to make',
269	  [STATUS_NEEDS_HUMAN_FAILURE]: 'a break to diagnose',
270	};
271	
272	// The outcome as its canonical word ('done' | 'delivered' | 'obsolete' | null) —
273	// the engine's decoder, which maps every legacy spelling straight to today's.
274	export const outcomeOf = decodeOutcome;
275	
276	// How long the item has sat where it is. Every transition is a label write, so
277	// `updated_at` is the last touch — the same quantity the janitor's rules count.
278	const idleMs = (item, now) => ms(now) - (ms(item?.updated_at) ?? ms(item?.created_at) ?? ms(now));
279	
280	// Warnings, each mirroring a real recovery rule rather than a display heuristic, so
281	// what the page flags is what the engine will actually act on — and how long the
282	// viewer waits for it.
283	//
284	// `isOpen(number)` answers whether a `Blocked-by` issue is still open — true, false,
285	// or null for one outside what the caller fetched. Unknown is never alarmed on.
286	export function warningsFor(item, now, { periodFor = () => null, isOpen = () => null } = {}) {
287	  const out = [];
288	  const state = stateOf(item);
289	  const idle = idleMs(item, now);
290	  if (state === STATUS_RUNNING_EXECUTOR && idle >= EXECUTING_LEASH_MS) {
291	    out.push({ level: 'serious', text: 'executing past the leash — the next scheduler run reclaims it' });
292	  }
293	  if (state === STATUS_RUNNING_AGENT && idle >= AGENT_LEASH_MS) {
294	    out.push({ level: 'serious', text: 'agent claim past the leash — the janitor reclaims it' });
295	  }
296	  if (state === STATUS_READY) {
297	    const per = periodFor(`${parseWorkItemTitle(item.title)?.pack}/${parseWorkItemTitle(item.title)?.task}`) ?? 86400e3;
298	    if (idle >= STALE_READY_PERIODS * per) out.push({ level: 'serious', text: 'ready but unpicked for ~2 periods' });
299	  }
300	  if (state === STATUS_BLOCKED) {
301	    // The standing-item model: blocked is the queue's healthy quiet state, not a
302	    // fault. A rolled item waiting out its Not-before never warns; what does warn is
303	    // the two things the engine would actually act on — dependencies unresolved past
304	    // the janitor's threshold, and an item DUE that the scheduler run has failed to ready.
305	    const { notBefore, blockedBy } = parseWorkItemBody(item.body);
306	    const wake = ms(notBefore);
307	    const depStates = blockedBy.map((n) => isOpen(n));
308	    if (wake !== null && wake > ms(now)) {
309	      // waiting out its stamped wake — healthy, whatever its age
310	    } else if (depStates.some((s) => s === true)) {
311	      if (idle >= STUCK_BLOCKED_MS) {
312	        out.push({ level: 'warning', text: `blocked on ${blockedBy.map((n) => `#${n}`).join(', ')} for over 2 days — the janitor flags stuck dependencies` });
313	      }
314	    } else if (!depStates.some((s) => s === null)) {
315	      // Nothing blocks it any more: the next scheduler run readies it. Due only measures from
316	      // the stamped wake — with dependencies the closing time is not on this item,
317	      // and a guess would alarm on an item that became due minutes ago.
318	      if (wake !== null && ms(now) - wake >= DUE_SLACK_MS) {
319	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
320	      } else if (wake === null && blockedBy.length === 0 && idle >= DUE_SLACK_MS) {
321	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
322	      }
323	    }
324	  }
325	  if (state === PARKED) {
326	    // What the park is asking for — an approval waiting on a reviewer is not the
327	    // same alarm as a broken run. Whether the break also holds the task's lane is
328	    // the declaration's word, not the park's, and the roster's next ask says it.
329	    const t = triageOf(item);
330	    out.push({
331	      level: isBlockingPark(item) ? 'critical' : 'warning',
332	      text: t ? `parked for a human — ${TRIAGE_TEXT[t]}` : 'parked for a human — unclassified',
333	    });
334	  }
335	  if (state === 'torn') out.push({ level: 'warning', text: 'wearing more than one state label' });
336	  if (state === 'unlabelled') out.push({ level: 'warning', text: 'open with no state label' });
337	  return out;
338	}
339	
340	// An open item, decorated with everything the queue lane renders.
341	export function describeItem(item, now, opts = {}) {
342	  // A marked issue keeps the person's own title, so its task comes from the worker
343	  // path its machine block names — without that the page would render every request
344	  // run as an item belonging to no task at all.
345	  const parsed = parseWorkItemTitle(item.title)
346	    ?? (taskIdFromPath(parseWorkItemBody(item.body).taskPath) ? { ...taskIdFromPath(parseWorkItemBody(item.body).taskPath), qualifier: null } : null)
347	    ?? { pack: null, task: null, qualifier: null };
348	  const body = parseWorkItemBody(item.body);
349	  const state = stateOf(item);
350	  return {
351	    number: item.number,
352	    // The issue's own title, kept as GitHub has it: a surface that NAMES one item —
353	    // rather than counting them — has nothing else to call it by.
354	    title: item.title,
355	    key: parsed.pack && parsed.task ? `${parsed.pack}/${parsed.task}` : null,
356	    ...parsed,
357	    state,
358	    outcome: outcomeOf(item),
359	    triage: triageOf(item),
360	    blockingPark: state === PARKED && isBlockingPark(item),
361	    urgent: hasLabel(item, URGENT),
362	    labels: labelNames(item),
363	    notBefore: body.notBefore,
364	    blockedBy: body.blockedBy,
365	    taskPath: body.taskPath,
366	    // When somebody created or force-woke this item, or null for one the scheduler filed.
367	    woken: body.woken ?? null,
368	    // The roll's record: when the last ask declined, why, and the stamped wake.
369	    lastVerdict: parseLastVerdict(item.body),
370	    createdAt: item.created_at,
371	    updatedAt: item.updated_at,
372	    closedAt: item.closed_at ?? null,
373	    idleMs: idleMs(item, now),
374	    comments: item.comments ?? 0,
375	    warnings: warningsFor(item, now, opts),
376	  };
377	}
378	
379	// --- the roster ----------------------------------------------------------------
380	
381	// The conditions a roster entry's declaration states. A declaration that was read
382	// (`parseDeclaration`'s object) carries `preconditions` as the list it states, `[]`
383	// for an absent key, or null for a field it could not read; an entry that never got
384	// a declaration (null — an orphan, a file the API did not return) is unknown whole.
385	// The key absent on a declaration object is the empty expression here too, so a
386	// caller building the object by hand reads the same way: only null means "not read".
387	const statedPreconditions = (declaration) => {
388	  if (declaration === null || typeof declaration !== 'object') return null;
389	  return declaration.preconditions === undefined ? [] : declaration.preconditions;
390	};
391	
392	// The trigger the same entry states. A caller building the object by hand may state
393	// only the conditions, so the door runs here too and the two reads stay one rule.
394	const statedTrigger = (declaration) => {
395	  if (declaration === null || typeof declaration !== 'object') return null;
396	  return withTrigger(declaration.trigger, statedPreconditions(declaration));
397	};
398	
399	// One row per DECLARED task, whether or not it has ever run — a task that has never
400	// produced an item is exactly the interesting case, and an issue-derived list would
401	// omit it entirely.
402	export function buildRoster({ tasks = [], items = [], now, schedule, isOpen }) {
403	  const byKey = new Map();
404	  for (const it of items) {
405	    const p = parseWorkItemTitle(it.title);
406	    if (!p) continue;
407	    const key = `${p.pack}/${p.task}`;
408	    if (!byKey.has(key)) byKey.set(key, []);
409	    byKey.get(key).push(it);
410	  }
411	
412	  return tasks.map((t) => {
413	    const key = `${t.pack}/${t.task}`;
414	    const mine = (byKey.get(key) ?? []).slice()
415	      .sort((a, b) => ms(b.created_at) - ms(a.created_at));
416	    const open = mine.filter((i) => i.state === 'open');
417	    const closed = mine.filter((i) => i.state === 'closed');
418	    const read = describeCadence(statedPreconditions(t.declaration), statedTrigger(t.declaration));
419	
420	    // The calendar answers only a `due:` cadence, and only where the repo has a
421	    // schedule to anchor it on; every other reading carries its own note instead, so
422	    // an unreadable declaration yields no anchor rather than a guessed one.
423	    let next = null;
424	    let anchorNote = read.anchorNote;
425	    if (read.cadence?.kind === 'due') {
426	      if (!schedule) anchorNote = 'no schedule configured';
427	      else next = nextAnchor(read.cadence.cadence, schedule, now);
428	    }
429	
430	    const current = open.length
431	      ? describeItem(open[0], now, { periodFor: () => read.periodMs, isOpen })
432	      : null;
433	
434	    return {
435	      key,
436	      pack: t.pack,
437	      task: t.task,
438	      path: t.path,
439	      declaration: t.declaration ?? null,
440	      frequency: read.frequency,
441	      cadence: read.cadence,
442	      scheduled: read.scheduled,
443	      holdsOnFailure: read.holdsOnFailure,
444	      holdsOnAnyPark: read.holdsOnAnyPark,
445	      nextAnchor: next,
446	      anchorNote,
447	      periodMs: read.periodMs,
448	      current,
449	      nextAsk: nextAskOf(current, next, anchorNote, read.holdsOnFailure, read.holdsOnAnyPark),
450	      openCount: open.length,
451	      lastClosed: closed.length ? describeItem(closed[0], now) : null,
452	      history: closed.map((i) => describeItem(i, now)),
453	    };
454	  });
455	}
456	
457	// What will actually happen to this task next, derived from the standing item where
458	// one exists — the calendar answers only when no item does (the next instantiation).
459	// This is where the standing-item model's facts become the roster's advice:
460	//   - the stamped Not-before IS the schedule (S28), so it wins over the
461	//     computed anchor;
462	//   - a park holds the task's lane only where the declaration says so — with
463	//     `last-run-not-failed` for the failure park, or `last-run-not-parked` for
464	//     all four. Showing an anchor there would promise a run the task itself
465	//     declines, and showing `held` anywhere else would hide a run the scheduler
466	//     files on schedule around the park;
467	//   - every park the declaration does not name consumed its occurrence and leaves
468	//     the lane open, so the next anchor stands beside it.
469	function nextAskOf(current, anchor, anchorNote, holdsOnFailure, holdsOnAnyPark) {
470	  if (!current) return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
471	  if (current.state === STATUS_READY) return { kind: 'ready', urgent: current.urgent };
472	  if (current.state === STATUS_RUNNING_EXECUTOR || current.state === STATUS_RUNNING_AGENT) {
473	    return { kind: 'running', phase: current.state === STATUS_RUNNING_AGENT ? 'agent' : 'executor' };
474	  }
475	  if (current.state === PARKED) {
476	    if (holdsOnAnyPark === true || (current.blockingPark && holdsOnFailure === true)) return { kind: 'held' };
477	    return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
478	  }
479	  if (current.state === STATUS_BLOCKED) {
480	    if (current.notBefore) return { kind: 'wake', at: new Date(current.notBefore) };
481	    return current.blockedBy.length ? { kind: 'deps', on: current.blockedBy } : { kind: 'ready-soon' };
482	  }
483	  // torn / unlabelled — off the state machine until the janitor repairs it.
484	  return { kind: 'off-machine' };
485	}
486	
487	// --- what is about to happen ------------------------------------------------------
488	
489	// The next 24 hours as UTC hour buckets, each carrying the task rows whose next ask
490	// lands in it. The strip this draws answers a question no single row can: whether the
491	// day's scheduled work is spread out or piled into one hour.
492	//
493	// FLEET OR REPO, the same reduction: the caller hands in whatever roster rows it has,
494	// one member's or every member's, and a row carries the repo it came from where that
495	// matters.
496	//
497	// A `held` next ask is placed at NOW and marked critical rather than left out. A task
498	// whose blocking park stops it being scheduled at all has no future anchor, and
499	// dropping it would draw the emptiest strip on the worst-off repo — the one case where
500	// an empty hour must not read as a quiet one.
501	export const WAKE_STRIP_HOURS = 24;
502	
503	export function wakeStrip(rows, now, { hours = WAKE_STRIP_HOURS } = {}) {
504	  const start = new Date(now);
505	  start.setUTCMinutes(0, 0, 0);
506	  const key = (t) => new Date(t).toISOString().slice(0, 13);
507	  const buckets = Array.from({ length: hours }, (_, i) => ({
508	    hour: key(start.getTime() + i * 3600e3),
509	    tasks: [],
510	    held: 0,
511	  }));
512	  const byHour = new Map(buckets.map((b) => [b.hour, b]));
513	
514	  for (const row of rows ?? []) {
515	    const ask = row?.nextAsk;
516	    if (!ask) continue;
517	    const held = ask.kind === 'held';
518	    // Only the two kinds that name a MOMENT land on a strip of hours: an anchor (the
519	    // calendar's next fire) and a wake (a stamped Not-before, which IS the schedule).
520	    // `ready`, `running` and `deps` are happening or waiting on something other than
521	    // the clock, and belong to the row rather than to a future hour.
522	    const at = held ? start.getTime() : (ask.kind === 'anchor' || ask.kind === 'wake' ? ms(ask.at) : null);
523	    if (at === null) continue;
524	    const bucket = byHour.get(key(at));
525	    if (!bucket) continue;                      // past the strip's far end — not this day's business
526	    bucket.tasks.push({ key: row.key, repo: row.repo ?? null, held });
527	    if (held) bucket.held += 1;
528	  }
529	
530	  const peak = buckets.reduce((n, b) => Math.max(n, b.tasks.length), 0);
531	  return { from: buckets[0]?.hour ?? null, hours: buckets, peak };
532	}
533	
534	// Outcome tallies over the closed items the scan actually saw. `scanned` travels
535	// with them: every count here is over a window, and a window is not "all of it".
536	export function outcomeTally(rows) {
537	  const t = { done: 0, delivered: 0, obsolete: 0, none: 0 };
538	  for (const r of rows) for (const h of r.history) t[h.outcome ?? 'none'] += 1;
539	  return t;
540	}
541	
542	// --- the protocol comments ------------------------------------------------------
543	
544	// Which of the three markers a comment carries. The markers are HTML comments so a
545	// human reading the issue sees prose; the page shows the protocol beat instead.
546	export function commentKind(body) {
547	  const b = String(body ?? '');
548	  if (b.includes(EPISODE_MARKER)) return 'episode';
549	  if (b.includes(HANDOFF_MARKER)) return 'handoff';
550	  if (b.includes(CLAIM_MARKER)) return 'claim';
551	  return null;
552	}
553

