40	// Severity ladder, worst first. The order IS the sort, so it is stated once here
41	// rather than implied by comparisons scattered through the render.
42	export const LEVELS = ['critical', 'serious', 'warning', 'info', 'ok'];
43	const levelRank = (l) => {
44	  const i = LEVELS.indexOf(l);
45	  return i === -1 ? LEVELS.length : i;
46	};
47	
48	const ms = (t) => (t == null ? null : new Date(t).getTime());
49	
50	// --- the canon side of the comparison ---------------------------------------------
51	
52	// The canon's versions are lifted as TEXT, like every declaration field: the page
53	// reads the canon over the API, where there is nothing to import. Comment-stripped
54	// so prose naming the field can never be mistaken for it, and null — never a guess —
55	// when the pattern is not there.
56	const ENGINE_VERSION_RE = new RegExp(String.raw`ENGINE_VERSION\s*=\s*'?(${VERSION_SOURCE})'?`);
57	const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[{,\s])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
