59	export function parseEngineVersion(text) {
60	  const m = ENGINE_VERSION_RE.exec(stripComments(String(text ?? '')));
61	  return m ? versionFromLiteral(m[1]) : null;
62	}
63	
64	export function parsePackVersion(text) {
65	  const m = PACK_VERSION_RE.exec(stripComments(String(text ?? '')));
