69	// --- mount freshness ------------------------------------------------------------
70	
71	// Whether a member's mount is current, judged on the versions it has installed —
72	// the only thing left to judge it on, and the only thing that was ever right. The
73	// `ref` and `updated` that sat beside them held the provenance of the last FULL
74	// re-vendor, so a member converging nightly carried a months-old pair forever and
75	// anything judging either read every healthy member as behind or stalled (#1065,
76	// the same class as #786); #1252 deleted both.
77	//
78	// `canon` is the reference to compare against: its live `engineVersion` and the
79	// canon's own per-pack versions (`packVersions`, possibly partial — the loader
80	// fetches only the packs members actually stamp). A pack the canon side cannot
81	// price is counted `unknownPacks`, never silently judged current. With no canon
82	// supplied the honest answer is `unknown`, not `current`.
83	export function mountState(declaration, canon = null) {
84	  if (!declaration) return { state: 'none', engineVersion: null };
85	  // The shape reader canonicalizes as it goes: a version is stored data, and a pack
86	  // renamed since it was written still keys under the old spelling in the retired
87	  // block, which must compare rather than read as unknown.
88	  const { engineVersion, packVersions } = installedVersions(declaration);
89	
90	  if (engineVersion == null && Object.keys(packVersions).length === 0) {
91	    // A stamp with no versions predates the versioned flows entirely — this member
92	    // has not converged since they landed, which is its own kind of stale.
93	    return { state: 'unversioned', engineVersion };
94	  }
95	  if (canon?.engineVersion == null) return { state: 'unknown', engineVersion };
96	
97	  if (isVersion(engineVersion) && versionAbove(canon.engineVersion, engineVersion)) {
98	    return { state: 'behind-engine', engineVersion, canonEngineVersion: canon.engineVersion };
99	  }
100	
101	  const behindPacks = [];
102	  let comparedPacks = 0;
103	  let unknownPacks = 0;
104	  for (const [pack, version] of Object.entries(packVersions ?? {})) {
105	    const canonVersion = canon.packVersions?.[pack];
106	    if (canonVersion == null) { unknownPacks += 1; continue; }
107	    comparedPacks += 1;
108	    if (versionAbove(canonVersion, version)) behindPacks.push({ pack, version, canonVersion });
109	  }
110	  if (behindPacks.length) {
111	    return { state: 'behind', engineVersion, behindPacks, comparedPacks, unknownPacks };
112	  }
113	  return { state: 'current', engineVersion, comparedPacks, unknownPacks };
114	}
