116	// --- is anyone working here ------------------------------------------------------
117	
118	// How long a member may go without GENUINE PROJECT WORK before the fleet view calls it
119	// sleepy. Short on purpose (owner, 2026-09-13): a repo crossing back and forth is fine,
120	// because this is a reading of the last fortnight rather than a verdict on the project.
121	export const SLEEPY_DAYS = 14;
122	
123	// Sleepy, awake, or not classified. The input is `commitClasses` over the window
124	// commit listing, so the test is the claudinite-tasks pack's own substantive-commit
125	// one and a member reads quiet here exactly when its own preconditions read it quiet.
126	//
127	// THREE STATES, and the third is the point: a member whose commit listing was withheld
128	// under the page's budget is `unknown`, never `sleepy`. A repo nobody looked at and a
129	// repo nobody worked on are not the same fact, and only one of them is news.
130	export function sleepState(classes, { now } = {}) {
131	  if (!classes) return { state: 'unknown', days: SLEEPY_DAYS, lastMeaningfulAt: null };
132	  const since = now - SLEEPY_DAYS * DAY_MS;
133	  // The window the listing actually reached. A read that stopped at a full page covers
134	  // the recent end — which is the end this question is about — so a truncated listing
135	  // still answers it; one whose window starts INSIDE the fortnight does not.
136	  const from = classes.from == null ? null : new Date(classes.from).getTime();
137	  if (from != null && from > since) return { state: 'unknown', days: SLEEPY_DAYS, lastMeaningfulAt: classes.lastMeaningfulAt };
138	  const awake = classes.lastMeaningfulAt != null && classes.lastMeaningfulAt >= since;
139	  return {
140	    state: awake ? 'awake' : 'sleepy',
141	    days: SLEEPY_DAYS,
142	    lastMeaningfulAt: classes.lastMeaningfulAt,
143	    // The one exclusion the cheap test cannot apply, named where the state is decided
144	    // rather than in a footnote nobody reads beside the row it changes.
145	    caveat: 'commits are classified from the listing, so a commit that touched only .claudinite/ counts as work unless its message says otherwise',
146	  };
147	}
