227	
228	  const declaredTasks = paths ? taskDeclarationPaths(paths, declaration).length : null;
229	  const periodFor = () => null;   // the fleet row needs no per-task cadence
230	  const described = open.map((i) => describeItem(i, now, { periodFor }));
231	
