251	  const actions = parked.filter((d) => !d.blockingPark && d.triage === STATUS_NEEDS_HUMAN_ACTION);
252	  const decisions = parked.filter((d) => !d.blockingPark && ![STATUS_NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_ACTION].includes(d.triage));
253	  const inbox = [...actions, ...decisions];
254	  const warned = described.filter((d) => d.state !== PARKED && d.warnings.length);
255	
256	  const outcomes = { done: 0, delivered: 0, obsolete: 0, none: 0 };
257	  for (const i of closed) outcomes[outcomeOf(i) ?? 'none'] += 1;
258	
259	  const lastActivity = closed
260	    .map((i) => ms(i.closed_at) ?? ms(i.updated_at))
261	    .filter(Boolean)
262	    .sort((a, b) => b - a)[0] ?? null;
263	
264	  const runSummary = summariseRuns(runs ?? [], now, usage);
265	  const ci = ciStatus(runs ?? [], defaultBranch);
266	  // A DORMANT member declared its own scheduler stopped, and the fleet takes that at
267	  // its word (owner, 2026-09-13): its mount is not measured and its scheduler is not
268	  // judged. Nothing converges it and no fleet-wide operation touches it, so both
269	  // verdicts would be findings nobody owns — which is a different thing from the row
270	  // being quiet about the repo, since the row says dormant where they would have sat.
271	  const dormant = isDormant(declaration);
272	  const mount = dormant
