274	    : mountState(declaration, canon);
275	  const classes = commitClasses(windowCommits);
276	  const sleep = sleepState(classes, { now });
277	
278	  const n = (count, word) => `${count} ${word}${count > 1 ? 's' : ''}`;
279	  // Every reason carries a `kind`, because the row shows some of these twice
280	  // otherwise: parks have their own column with an estimate beside them, the mount
281	  // is a badge on the pack count, and CI is a dot. The RANKING still reads all of
282	  // them — a member is ordered by everything true of it — and only the rendering
283	  // drops what already has a cell of its own.
284	  const reasons = [];
285	  if (holding.length) {
286	    reasons.push({ kind: 'park', level: 'critical', text: `${n(holding.length, 'item')} parked broken — a run to diagnose` });
287	  }
288	  if (inbox.length) {
289	    reasons.push({ kind: 'park', level: 'serious', text: `${n(inbox.length, 'item')} parked for a person — an action or a decision` });
290	  }
291	  if (approvals.length) {
292	    reasons.push({ kind: 'park', level: 'warning', text: `${n(approvals.length, 'PR')} waiting for approval` });
293	  }
294	  if (runSummary.consecutiveFailures > 0 && !dormant) {
295	    reasons.push({
296	      kind: 'scheduler',
297	      level: runSummary.consecutiveFailures > 1 ? 'critical' : 'serious',
298	      text: `scheduler last run failed${runSummary.consecutiveFailures > 1 ? ` (${runSummary.consecutiveFailures} in a row)` : ''}`,
