300	  }
301	  if (warned.length) {
302	    reasons.push({ kind: 'park', level: 'serious', text: `${n(warned.length, 'item')} tripping a recovery rule` });
303	  }
304	  if (dormant) {
305	    // Not a fault, and not a silence either: the reader is told why the two Claudinite
306	    // verdicts are absent from this row.
307	    reasons.push({ kind: 'mount', level: 'info', text: 'dormant — its scheduler is stopped by declaration, so its mount and scheduler are not measured' });
308	  } else if (mount.state === 'behind-engine') {
309	    reasons.push({ kind: 'mount', level: 'serious', text: `mount is on engine v${mount.engineVersion}, canon is v${canon?.engineVersion}` });
310	  } else if (mount.state === 'behind') {
311	    reasons.push({ kind: 'mount', level: 'info', text: `mount behind canon on ${mount.behindPacks.map((p) => p.pack).join(', ')}` });
312	  } else if (mount.state === 'unversioned') {
313	    reasons.push({ kind: 'mount', level: 'warning', text: 'declares Claudinite but records no installed versions — the mount has never been converged' });
314	  } else if (mount.state === 'none') {
315	    reasons.push({ kind: 'mount', level: 'warning', text: 'declares Claudinite but carries no mount stamp' });
316	  }
317	  // A repo that declares tasks and has never produced a work item is not idle — its
318	  // scheduler is not running. That is invisible in every per-repo number here, which
319	  // is exactly why the fleet view is the place it shows up.
320	  if (declaredTasks !== null && declaredTasks > 0 && work.length === 0 && !dormant) {
321	    reasons.push({ kind: 'scheduler', level: 'serious', text: `${declaredTasks} task${declaredTasks > 1 ? 's' : ''} declared, no work item ever created` });
322	  }
323	  if (ci.state === 'failing') {
324	    // The member's own CI, said in the member's own words: this is not the scheduler
325	    // failing, and the two must not read as the same alarm.
326	    reasons.push({ kind: 'ci', level: 'warning', text: 'the repo\'s own CI is failing on its default branch' });
327	  }
328	  if (declaration.packs?.length === 0) {
329	    reasons.push({ kind: 'packs', level: 'warning', text: 'declares no packs' });
330	  }
331	
332	  const level = reasons.length ? reasons.map((r) => r.level).sort((a, b) => levelRank(a) - levelRank(b))[0] : 'ok';
333	
334	  return {
335	    repo,
336	    status: 'adopted',
337	    level,
338	    reasons,
339	    // GitHub's own two facts about the repository, carried through untouched: the row
340	    // shows `private` because who can see a member is part of recognising it.
341	    private: isPrivate,
342	    dormant,
343	    // Whether anything MEANINGFUL landed here lately — `sleepState` above. Distinct
344	    // from dormant in both directions: a sleepy member is fully in the fleet and every
345	    // fleet-wide operation still reaches it.
346	    sleep,
347	    packs: (declaration.packs ?? []).map((p) => (typeof p === 'string' ? p : p?.id)).filter(Boolean),
348	    declaredTasks,
349	    open: { total: open.length, byState, urgent: described.filter((d) => d.urgent).length },
350	    parked: parked.length,
351	    parkedHolding: holding.length,
352	    parkedApprovals: approvals.length,
353	    parkedActions: actions.length,
354	    parkedDecisions: decisions.length,
355	    parkedInbox: inbox.length,
356	    warned: warned.length,
357	    closedSeen: closed.length,
358	    outcomes,
359	    lastActivity,
360	    runs: runSummary,
361	    ci,
362	    stars,
363	    // What this member's own packs report, straight through from the read: the
364	    // summary judges nothing about it. A contribution never feeds a reason, a level
365	    // or the ranking — attention is earned by what the engine can defend, and a pack
366	    // cannot rank across a fleet it does not know.
367	    // The one item of this member's worth prodding a reader about, ranked by the same
368	    // rules the repo page's work table ranks by. Computed here because this is the only
369	    // place the described items exist, and nothing above re-reads them.
370	    top: pickCandidate(described.map((d) => itemCandidate(repo, d))),
371	    contributions: read.contributions ?? null,
372	    live: read.live ?? null,
373	    lastCommit: head?.committedAt ? ms(head.committedAt) : null,
374	    // Null all the way through when the read did not happen, so the row draws "not
375	    // read" rather than an empty quarter that reads as a repo nobody touched.
376	    commits: commitDays(commits, { now, classes }),
377	    work: humanWork(items, prs, now),
378	    mount,
379	    schedule: declaration.taskScheduler ?? null,
