382	
383	// A read that failed says something different depending on how. 404 on a repo the
384	// roster names is almost always "not shared with this viewer", which is a permissions
385	// fact rather than a fault.
386	function describeReadError(error) {
387	  const status = error?.status;
388	  if (status === 'budget') return 'not read — this page is holding back your last requests; sign in or wait for the reset';
389	  if (status === 404) return 'not visible to you — the roster names it, your credential cannot see it';
390	  if (status === 403) return 'forbidden — rate limit, or your credential lacks access';
391	  if (status === 401) return 'your credential was rejected';
392	  return error?.message ? `unreadable — ${error.message}` : 'unreadable';
393	}
394	
395	// The repo's OWN CI, which is a different question from the scheduler's health: one
396	// says whether this project builds, the other whether Claudinite is running here. They
397	// are read from the same list and must never be conflated — a green scheduler on a
398	// repo whose tests are red is not a healthy member.
399	//
400	// The default branch's most recent completed run is the answer; a `schedule` run is
401	// excluded because that is the queue's own scheduler run, reported separately.
402	export function ciStatus(runs, defaultBranch) {
403	  const mine = (runs ?? []).filter((r) => r.event !== 'schedule'
404	    && (!defaultBranch || !r.head_branch || r.head_branch === defaultBranch));
405	  const inFlight = mine.some((r) => r.status === 'in_progress' || r.status === 'queued');
406	  const last = mine.find((r) => r.status === 'completed');
407	  if (!last) return { state: inFlight ? 'running' : 'unknown', at: null, name: null };
408	  const state = last.conclusion === 'success' ? 'passing'
409	    : (last.conclusion === 'cancelled' || last.conclusion === 'skipped') ? 'unknown'
410	      : 'failing';
411	  return { state: inFlight ? 'running' : state, at: ms(last.created_at), name: last.name ?? null, url: last.html_url ?? null };
412	}
413	
414	// What is waiting on a PERSON here, as opposed to on the queue: issues that are not
415	// Claudinite work items, and open pull requests. Both come out of the issue page the
416	// row already reads, so this costs nothing and stops at that window — an issue older
417	// than the window is not counted, and the panel says the window is a window.
418	export function humanWork(items, prs, now) {
419	  const open = (items ?? []).filter((i) => i.state === 'open' && !isWorkItem(i));
420	  const oldest = (list) => list.map((i) => ms(i.created_at)).filter(Boolean).sort((a, b) => a - b)[0] ?? null;
421	  const openPrs = (prs ?? []).filter((p) => !p.draft);
422	  return {
423	    issues: open.length,
424	    issuesOldest: oldest(open),
425	    prs: openPrs.length,
426	    drafts: (prs ?? []).length - openPrs.length,
427	    prsOldest: oldest(openPrs),
428	    now,
429	  };
430	}
431	
432	// The scheduler's own health. Only the workflow that drives the queue matters here —
433	// a failing unrelated CI run is the repo's business, not the fleet scheduler's — so
434	// runs are filtered to scheduled ones before anything is counted.
435	//
436	// THE HEARTBEAT NEEDS A SECOND SOURCE. The runs listing is one page across every
437	// workflow the repo has — the scheduler, the executor and the member's own CI — so on
438	// a busy member that page covers a few hours, and a member whose last scheduler run is
439	// older than it is indistinguishable from one that has never run. "Never ran" is
440	// exactly the critical verdict, so the difference is not one to guess at.
441	//
442	// The fold's hour tier is that second source: three days of per-hour scheduler counts,
443	// appended past its own watermark from a listing it pages properly. It is coarser —
444	// an hour, not a timestamp — so it is used as a FLOOR: it can only push `lastAt`
445	// further back than the live page reached, and can only turn "never ran" into "ran".
446	// A member with no fold reads its heartbeat from the live page alone and says so.
447	export function summariseRuns(runs, now, usage = null) {
448	  const scheduled = runs.filter((r) => r.event === 'schedule');
449	  const completed = scheduled.filter((r) => r.status === 'completed');
450	  const inFlight = runs.filter((r) => r.status === 'in_progress' || r.status === 'queued').length;
451	
452	  // Consecutive failures from the most recent backwards: one failure is noise, a run
453	  // of them is a member that has stopped working.
454	  let consecutiveFailures = 0;
455	  for (const r of completed) {
456	    if (r.conclusion === 'success') break;
457	    if (r.conclusion === 'cancelled' || r.conclusion === 'skipped') continue;
458	    consecutiveFailures += 1;
459	  }
460	
461	  const liveLastAt = scheduled.map((r) => ms(r.created_at)).filter(Boolean).sort((a, b) => b - a)[0] ?? null;
462	  const foldedLastAt = lastFoldedScheduler(usage);
463	  const lastAt = liveLastAt !== null && (foldedLastAt === null || liveLastAt >= foldedLastAt)
464	    ? liveLastAt : foldedLastAt;
465	
466	  return {
467	    scheduled: scheduled.length,
468	    inFlight,
469	    consecutiveFailures,
470	    lastAt,
471	    // Where that timestamp came from, and therefore how precise it is: a live run is
472	    // exact, a folded hour is the hour it started in. `null` when neither answered.
473	    lastAtSource: lastAt === null ? null : (lastAt === liveLastAt ? 'live' : 'folded'),
474	    // Whether the fold was read at all, so a member with none can say its heartbeat
475	    // rests on one page of runs rather than implying the two agreed.
476	    foldRead: Boolean(usage?.hours),
477	    // No scheduled run in EITHER source is not "healthy" — it is "we have never seen
478	    // this member's scheduler", which the row must be able to say. A member with no
479	    // fold can still only be reporting the page's own depth, which `foldRead` states.
480	    everRan: scheduled.length > 0 || foldedLastAt !== null,
481	  };
482	}
483	
484	// The newest hour the fold recorded a scheduler run in, as that hour's start. A floor,
485	// never a claim about the minute: the tier counts runs per hour and says nothing about
486	// where inside one they landed.
487	export function lastFoldedScheduler(usage) {
488	  const hours = usage?.hours;
489	  if (!hours) return null;
490	  const newest = Object.entries(hours)
491	    .filter(([, row]) => typeof row?.scheduler === 'number' && row.scheduler > 0)
492	    .map(([hour]) => hour)
493	    .sort()
494	    .pop();
495	  return newest ? ms(`${newest}:00:00Z`) : null;
496	}
497	
498	// --- the fleet ------------------------------------------------------------------
499	
500	// Worst first, then by how much is waiting. Ties break on the repo name so the order
501	// is stable across loads — a table that reshuffles under you is unreadable.
502	export function rankMembers(summaries) {
503	  return [...summaries].sort((a, b) =>
504	    levelRank(a.level) - levelRank(b.level)
505	    || (b.parked ?? 0) - (a.parked ?? 0)
506	    || (b.warned ?? 0) - (a.warned ?? 0)
507	    || (b.open?.total ?? 0) - (a.open?.total ?? 0)
508	    || a.repo.localeCompare(b.repo));
509	}
510	
511	// The headline numbers. Each is a count of MEMBERS needing something, not a count of
512	// things — "3 members need you" is actionable where "47 open items" is not.
513	export function rollUp(summaries) {
514	  const adopted = summaries.filter((s) => s.status === 'adopted');
515	  // The fleet's machinery figures are about the AWAKE members: a dormant one declared
516	  // its scheduler stopped, so counting it as failing, never-run or behind reports an
517	  // obedient repo as a fault (owner, 2026-09-13).
518	  const awake = adopted.filter((s) => !s.dormant);
519	  const outcomes = { done: 0, delivered: 0, obsolete: 0, none: 0 };
520	  for (const s of adopted) for (const [k, v] of Object.entries(s.outcomes ?? {})) outcomes[k] += v;
521	
522	  return {
523	    members: summaries.length,
524	    adopted: adopted.length,
525	    notAdopted: summaries.filter((s) => s.status === 'not-adopted').length,
526	    unreadable: summaries.filter((s) => s.status === 'unreadable').length,
527	    withheld: summaries.filter((s) => s.status === 'withheld').length,
528	    needAttention: adopted.filter((s) => levelRank(s.level) <= levelRank('serious')).length,
529	    parkedMembers: adopted.filter((s) => s.parked > 0).length,
530	    parkedItems: adopted.reduce((n, s) => n + s.parked, 0),
531	    parkedHolding: adopted.reduce((n, s) => n + (s.parkedHolding ?? 0), 0),
532	    parkedInbox: adopted.reduce((n, s) => n + (s.parkedInbox ?? 0), 0),
533	    parkedActions: adopted.reduce((n, s) => n + (s.parkedActions ?? 0), 0),
534	    parkedDecisions: adopted.reduce((n, s) => n + (s.parkedDecisions ?? 0), 0),
535	    parkedApprovals: adopted.reduce((n, s) => n + (s.parkedApprovals ?? 0), 0),
536	    warnedItems: adopted.reduce((n, s) => n + (s.warned ?? 0), 0),
537	    warnedMembers: adopted.filter((s) => s.warned > 0).length,
538	    failingMembers: awake.filter((s) => s.runs?.consecutiveFailures > 0).length,
539	    neverRan: awake.filter((s) => s.runs && !s.runs.everRan).length,
540	    behindMembers: awake.filter((s) => ['behind', 'behind-engine', 'unversioned'].includes(s.mount?.state)).length,
541	    // The two states the grid marks, counted so a filter can say how many it will show.
542	    dormantMembers: adopted.filter((s) => s.dormant).length,
543	    sleepyMembers: adopted.filter((s) => s.sleep?.state === 'sleepy').length,
544	    privateMembers: adopted.filter((s) => s.private).length,
545	    openItems: adopted.reduce((n, s) => n + (s.open?.total ?? 0), 0),
546	    inFlight: adopted.reduce((n, s) => n + (s.runs?.inFlight ?? 0), 0),
547	    declaredTasks: adopted.reduce((n, s) => n + (s.declaredTasks ?? 0), 0),
548	    outcomes,
549	  };
550	}
551	
552	// --- what a person is actually holding -------------------------------------------
553	
554	// What one parked item costs a person, in minutes, by WHAT THE PARK ASKS FOR (owner,
555	// 2026-08-22). Per kind rather than one flat rate, because the four parks are disjoint
556	// by remedy and cost accordingly: diagnosing a break is not merging a PR, and averaging
557	// them into one number made the figure mean four things at once.
558	//
559	// Keyed by the count names below, which are the triage labels one layer up:
560	// `broken` is `task:needs-human-failure` PLUS any park whose kind cannot be decoded
561	// (`parkOf` falls back to `failure`), so an unclassified park is priced as the thing
562	// it is treated as everywhere else.
563	export const PARK_MINUTES = Object.freeze({
564	  broken: 15,
565	  actions: 10,
566	  decisions: 3,
567	});
568	
569	// An approval is priced by SIZE, not by kind: a two-line docs merge and a nine-file
570	// refactor are the same label and not the same read.
571	export const APPROVAL_RATE = Object.freeze({ minutes: 1, lines: 200 });
572	
573	// Minutes to approve a PR of `changedLines`, or the rate's own floor when the size is
574	// unknown — which is every approval today, and deliberately not hidden. The page never
575	// reads a PR's size: `projectPull` keeps no line counts and the PRs arrive on the
576	// issues listing, which carries none, so a size would cost one extra request per open
577	// approval against `budget.mjs`'s ladder. Unknown stays unknown rather than becoming a
578	// zero or a guessed average: the floor is the smallest thing the rate can honestly say,
579	// which is what makes the total a LOWER BOUND rather than an estimate that might be high.
580	export const approvalMinutes = (changedLines = null) =>
581	  (Number.isFinite(changedLines) && changedLines > 0
582	    ? Math.max(1, Math.ceil((changedLines / APPROVAL_RATE.lines) * APPROVAL_RATE.minutes))
583	    : APPROVAL_RATE.minutes);
584	
585	// ONE parked item's own minutes, from the rates above — so a figure shown against a
586	// single item is one term of that sum rather than a second estimate. `park` is the
587	// item's own classification and nothing else: whether it blocks, and its triage label.
588	// Anything that is not a park has no figure at all here, by the same rule that keeps
589	// scheduler faults and recovery-rule trips out of the total.
590	export function parkMinutes(park) {
591	  if (!park) return null;
592	  // An undecodable park is priced as the thing it is treated as everywhere else.
593	  if (park.blocking || !park.triage) return PARK_MINUTES.broken;
594	  if (park.triage === STATUS_NEEDS_HUMAN_APPROVAL) return approvalMinutes();
595	  if (park.triage === STATUS_NEEDS_HUMAN_ACTION) return PARK_MINUTES.actions;
596	  return PARK_MINUTES.decisions;
597	}
598	
599	// The one caveat a single item's figure carries, and only the approvals carry it: the
600	// page never reads a PR's size, so an approval is charged the rate's floor and its
601	// figure can only be low. The same sentence `estimateNote` appends to a total.
602	export const parkMinutesNote = (park) =>
603	  (parkMinutes(park) != null && !park.blocking && park.triage === STATUS_NEEDS_HUMAN_APPROVAL
604	    ? 'PR size unread, so a lower bound'
605	    : null);
606	
607	// The vocabulary both the per-member row and the fleet rollup speak, so one function
608	// itemises both. Each field is a count of THINGS waiting; the two callers differ only
609	// in whether their things are one member's or the whole fleet's.
610	const attentionCounts = ({
611	  broken = 0, decisions = 0, actions = 0, approvals = 0, tripping = 0,
612	  schedulersFailing = 0, schedulersNeverRan = 0,
613	} = {}) => ({ broken, decisions, actions, approvals, tripping, schedulersFailing, schedulersNeverRan });
614	
615	// One member's attention, in the same shape the rollup uses.
616	export const memberAttention = (s) => attentionCounts({
617	  broken: s.parkedHolding ?? 0,
618	  decisions: s.parkedDecisions ?? 0,
619	  actions: s.parkedActions ?? 0,
620	  approvals: s.parkedApprovals ?? 0,
621	  tripping: s.warned ?? 0,
622	});
623	
624	// The fleet's. Schedulers are counted in MEMBERS here rather than in items, because a
625	// scheduler is a member-shaped thing — there is one per repo.
626	export const fleetAttention = (roll) => attentionCounts({
627	  broken: roll.parkedHolding,
628	  decisions: roll.parkedDecisions,
629	  actions: roll.parkedActions,
630	  approvals: roll.parkedApprovals,
631	  tripping: roll.warnedItems,
632	  schedulersFailing: roll.failingMembers,
633	  schedulersNeverRan: roll.neverRan,
634	});
635	
636	// Minutes of a person's time the parked work represents. ONLY the parks: every minute
637	// in here is attributable to an item wearing a `task:status:needs-human-<kind>` label,
638	// which is a thing a person can see on the issue and go and do.
639	//
640	// Two things a reader might expect are deliberately outside it, for the same reason.
641	// Scheduler faults are not a queue of work to get through. And a recovery-rule trip is
642	// not waiting on a person at all: it wears no label, it is derived from an item's state
643	// and age against the engine's own leashes, and what clears it is the janitor or the
644	// next scheduler run. Both are still REPORTED, in `attentionBreakdown` beside the
645	// figure — they are just not minutes of anyone's time.
646	export function estimateMinutes(counts) {
647	  const c = attentionCounts(counts);
648	  return c.broken * PARK_MINUTES.broken
649	    + c.actions * PARK_MINUTES.actions
650	    + c.decisions * PARK_MINUTES.decisions
651	    + c.approvals * approvalMinutes();
652	}
653	
654	// The sentence published beside the figure, so a reader can check the arithmetic
655	// instead of trusting it — and so the one thing the number cannot know says so itself.
656	// One definition, because both surfaces show the same total and a note that differed
657	// between them would be two claims about one calculation.
658	export const estimateNote = (counts) => {
659	  const c = attentionCounts(counts);
660	  const parts = [];
661	  if (c.broken) parts.push(`${PARK_MINUTES.broken}×${c.broken} broken`);
662	  if (c.actions) parts.push(`${PARK_MINUTES.actions}×${c.actions} action`);
663	  if (c.decisions) parts.push(`${PARK_MINUTES.decisions}×${c.decisions} decision`);
664	  if (c.approvals) parts.push(`${APPROVAL_RATE.minutes}×${c.approvals} approval`);
665	  if (!parts.length) return 'nothing parked';
666	  // The caveat rides with the approvals, because it is only about them: with no PR
667	  // size the rate can charge nothing above its floor, so the total can only be low.
668	  return parts.join(' + ') + (c.approvals ? ' · PR sizes unread, so a lower bound' : '');
669	};
670	
671	// WHAT the human attention is, not how much of it there is. "3 members need you"
672	// is the length of this morning's list; it does not say whether that is three merges
673	// to approve or three broken lanes, and those are not the same morning.
674	//
675	// The split already exists one level down — `summariseMember` separates a failure
676	// park from an inbox park from an approval park precisely because a page that rings
677	// identically for all of them teaches its reader to ignore the ring — and the rollup
678	// used to throw it away and re-merge them into one word.
679	//
680	// Ordered worst first, and a kind nobody is waiting on is absent rather than zero.
681	//
682	// A row is read two ways. Where there is room for prose — the lead card, the fleet
683	// tiles — `text` is printed as it stands. Where there is not, the member row's cell in
684	// a ten-column grid, `ui.mjs`'s `attentionMark` draws the row instead, and it needs the
685	// pieces rather than the sentence: `kind` to address a row without matching its words,
686	// `count` and `short` to write a line narrow enough to fit. So the sentence is composed
687	// here from the same two pieces the mark uses, and the two can never disagree.
688	export function attentionBreakdown(counts) {
689	  const c = attentionCounts(counts);
690	  const row = (kind, level, count, [one, many], [shortOne, shortMany], say) => count && {
691	    kind,
692	    level,
693	    count,
694	    short: count === 1 ? shortOne : shortMany,
695	    text: `${count} ${count === 1 ? one : many} ${say}`.trim(),
696	  };
697	  return [
698	    row('broken', 'critical', c.broken, ['task', 'tasks'], ['broken', 'broken'], 'broken'),
699	    row('schedulersFailing', 'critical', c.schedulersFailing, ['scheduler', 'schedulers'], ['scheduler failing', 'schedulers failing'], 'failing'),
700	    row('decisions', 'serious', c.decisions, ['item', 'items'], ['decision', 'decisions'], 'needing a decision'),
701	    row('actions', 'serious', c.actions, ['item', 'items'], ['action', 'actions'], 'needing something changed outside the code'),
702	    row('tripping', 'serious', c.tripping, ['item', 'items'], ['tripping', 'tripping'], 'tripping a recovery rule'),
703	    row('approvals', 'warning', c.approvals, ['item', 'items'], ['approval', 'approvals'], 'needing approval'),
704	    row('schedulersNeverRan', 'serious', c.schedulersNeverRan, ['scheduler', 'schedulers'], ['never ran', 'never ran'], 'never ran'),
705	  ].filter(Boolean);
706	}
707	
708	// Which packs the fleet uses, and how widely. Answers the question the canon actually
709	// asks of its fleet — "who would a change to this pack reach" — which no single
710	// member's page can.
711	export function packSpread(summaries) {
712	  const counts = new Map();
713	  for (const s of summaries) {
714	    for (const p of s.packs ?? []) counts.set(p, (counts.get(p) ?? 0) + 1);
715	  }
716	  return [...counts.entries()]
717	    .map(([pack, members]) => ({ pack, members }))
718	    .sort((a, b) => b.members - a.members || a.pack.localeCompare(b.pack));
719	}
720	
721	// Which tasks are running across the fleet, from the work items themselves. A task
722	// declared by a shared pack runs in many members, and its fleet-wide behaviour —
723	// especially a task that is parked in several at once — is a canon problem rather
724	// than any one member's.
725	export function taskSpread(reads, now) {
726	  const byTask = new Map();
727	  for (const read of reads) {
728	    for (const item of (read.items ?? []).filter(isWorkItem)) {
729	      const parsed = parseWorkItemTitle(item.title);
730	      if (!parsed) continue;
731	      const key = `${parsed.pack}/${parsed.task}`;
732	      if (!byTask.has(key)) byTask.set(key, { key, pack: parsed.pack, task: parsed.task, members: new Set(), open: 0, parked: 0, done: 0, failed: 0 });
733	      const row = byTask.get(key);
734	      row.members.add(read.repo);
735	      if (item.state === 'open') {
736	        row.open += 1;
737	        if (isParked(item)) row.parked += 1;
738	      } else {
739	        const outcome = outcomeOf(item);
740	        if (outcome === 'done' || outcome === 'delivered') row.done += 1;
741	        else if (outcome !== 'obsolete') row.failed += 1;
742	      }
743	    }
744	  }
745	  return [...byTask.values()]
746	    .map((r) => ({ ...r, members: r.members.size }))
747	    .sort((a, b) => b.parked - a.parked || b.members - a.members || a.key.localeCompare(b.key));
748	}
749	
750	export { URGENT };
751

