1	// What a pack's `public/` folder actually publishes, and who outside the pack reads it.
2	//
3	// A published surface is a promise, and a promise nobody renders drifts: this pack's
4	// shelf carried a hand-written table of "modules other packs import" that named an
5	// export (`landPr`) no file has ever had, claimed a folder held only named exports
6	// while nine of its modules opened with `export *`, and listed a consumer for a module
7	// nothing imports. None of that was visible in a diff, because the table and the code
8	// it described were edited in different changes.
9	//
10	// So the table is derived instead. `renderSurfaceReport` is pure over a tree already
11	// read into memory, which keeps the scope assertion honest — a caller that hands it an
12	// empty file set gets an error rather than an empty report that reads as "no surface".
13	//
14	// A WILDCARD is reported as its own state, never expanded into a name list. `export *`
15	// republishes whatever its target exports today, so the surface it publishes is not a
16	// fact about this file at all; rendering the target's current names would state a
17	// promise the folder has not made.
18	
19	import { readdirSync, readFileSync } from 'node:fs';
20	import { join, relative, sep } from 'node:path';
21	import { pathToFileURL } from 'node:url';
22	
23	// `export { a, b as c } from '…'` / `export { a, b }` — the named form, which is the
24	// only form that pins a surface. `as` matters: what the outside sees is the alias.
25	const RE_NAMED = /^export\s*\{([^}]*)\}/;
26	const RE_STAR = /^export\s*\*\s*(?:as\s+([\w$]+)\s+)?from\s*['"]([^'"]+)['"]/;
27	const RE_DECL = /^export\s+(?:async\s+)?(?:function\s*\*?\s*([\w$]+)|class\s+([\w$]+)|(?:const|let|var)\s+([\w$]+))/;
28	
29	// An `import {`/`export {` list may wrap across lines, and the path it comes from sits
30	// on the LAST of them; fold each one back onto its opening line before matching, or a
31	// multi-line import reads as a module consumed for no names at all.
32	function logicalLines(text) {
33	  const lines = text.split('\n');
34	  const out = [];
35	  for (let i = 0; i < lines.length; i++) {
36	    let line = lines[i];
37	    while (/^\s*(?:import|export)\s*\{/.test(line) && !line.includes('}') && i + 1 < lines.length) line += ' ' + lines[++i].trim();
38	    out.push(line);
39	  }
40	  return out;
41	}
42	
43	// The names one module publishes. `wildcards` are the `export * from` targets it
44	// opens with; a module carrying both a star and a list publishes MORE than its list,
45	// which is the case worth seeing in a report.
46	export function publishedNames(text) {
47	  const names = [];
48	  const wildcards = [];
49	  for (const line of logicalLines(text)) {
50	    let m;
51	    if ((m = line.match(RE_STAR))) {
52	      if (m[1]) names.push(m[1]);
53	      else wildcards.push(m[2]);
54	    } else if ((m = line.match(RE_DECL))) {
55	      names.push(m[1] || m[2] || m[3]);
56	    } else if ((m = line.match(RE_NAMED))) {
57	      for (const part of m[1].split(',')) {
58	        const n = part.trim().match(/^([\w$]+)(?:\s+as\s+([\w$]+))?$/);
59	        if (n) names.push(n[2] || n[1]);
60	      }
61	    }
62	  }
63	  return { names: [...new Set(names)].sort(), wildcards };
64	}
65	
66	// Who a reference belongs to. The buckets are the ones that carry different weight:
67	// a member's workflow names a path this repo cannot rewrite, another pack's production
68	// code is a live dependency, and a test is only the canon proving its own contract.
69	//
70	// The mount prefix comes off first, so the pack reached through `.claudinite/shared/`
71	// is the same pack. Without that, a member running this over its own mount reads the
72	// pack's internals as an external consumer and every name they import counts as taken —
73	// the inflation this report exists to avoid, arriving from the one root that makes the
74	// pack look most in demand.
75	export function consumerBucket(path, packDir) {
76	  path = path.replace(/^\.claudinite\/(?:shared|local)\//, '');
77	  if (path.startsWith(`${packDir}/`)) return 'own pack';
78	  if (path.startsWith('.github/workflows/') || path.endsWith('.yml')) return 'workflow';
79	  const test = path.includes('/test/') || path.endsWith('.test.mjs');
80	  if (path.startsWith('packs/') || path.startsWith('.claudinite/')) return test ? 'pack (test)' : 'pack';
81	  return test ? 'canon (test)' : 'canon';
82	}
83	
84	const BUCKET_ORDER = ['workflow', 'pack', 'pack (test)', 'canon', 'canon (test)', 'own pack'];
85	
86	// How a line reaches the module. A comment or a remedy sentence naming a MODULE is a
87	// mention, not a dependency: it breaks nothing when the surface moves, and counting it
88	// as a reader overstates who the promise is being kept for — the one number this report
89	// exists to get right. A DOCUMENT is the opposite case: being named in prose is the
90	// only way one is ever consumed, so for a `.md` every reference is a reader.
91	//
92	// `node` decides a run only where a command is what the line holds — at its start, or
93	// after a workflow's `run:`. Mid-sentence inside a quoted remedy it is prose describing
94	// a command, not one.
95	function reachOf(line, isDocument) {
96	  const braces = line.match(/(?:import|export)\s*\{([^}]*)\}\s*from/) || line.match(/\{([^}]*)\}\s*=\s*await\s+import/);
97	  if (braces) return { kind: 'import', names: braces[1].split(',').map((p) => p.trim().match(/^([\w$]+)/)?.[1]).filter(Boolean) };
98	  if (/(?:^|\s)(?:import|export)\s[^{]*from\s*['"]/.test(line) || /\bimport\s*\(/.test(line)) return { kind: 'import', names: [] };
99	  if (isDocument) return { kind: 'names', names: [] };
100	  if (/^\s*(?:\/\/|\*|#|\|)/.test(line)) return { kind: 'mention', names: [] };
